    def _is_texture_workflow_tool_log(message: str) -> bool:
        lowered = str(message or "").lower()
        return any(
            marker in lowered
            for marker in (
                "texconv",
                "real-esrgan",
                "ncnn",
                "chainner",
                "] stage ",
                "] convert ",
                "] build ",
                "] built ",
                "timed out",
            )
        )

    def _collect_crash_context() -> Dict[str, object]:
        nonlocal _cached_crash_context
        window = _active_main_window
        context: Dict[str, object] = {}
        app = QApplication.instance()
        if app is not None and app.thread() != QThread.currentThread():
            context.update(_cached_crash_context)
            _add_persisted_crash_breadcrumbs(context)
            return context
        if window is None:
            return context
        process_memory = _windows_process_memory_snapshot(os.getpid())
        if process_memory:
            context["process_memory"] = process_memory
        try:
            current_tab_index = window.main_tabs.currentIndex()
            if current_tab_index >= 0:
                context["current_tab"] = window.main_tabs.tabText(current_tab_index)
        except Exception:
            pass
        try:
            entry = window._current_archive_entry()
            if entry is not None:
                context["selected_archive_path"] = entry.path
                context["selected_archive_package"] = str(entry.pamt_path)
        except Exception:
            pass
        try:
            context["texconv_path"] = window.texconv_path_edit.text().strip()
        except Exception:
            pass
        try:
            context["archive_package_root"] = window.archive_package_root_edit.text().strip()
        except Exception:
            pass
        try:
            context["last_active_operation"] = dict(_last_active_operation)
        except Exception:
            pass
        try:
            context["runtime_event_tail"] = list(_runtime_event_ring)[-120:]
        except Exception:
            pass
        try:
            context["native_diagnostic_log_path"] = str(_native_diagnostic_log_path)
            context["native_diagnostic_event_tail"] = _read_jsonl_tail(_native_diagnostic_log_path, limit=120)
        except Exception:
            pass
        try:
            context["archive_renderer_backend"] = window._archive_model_renderer_backend()
            context["archive_preview_request_id"] = int(getattr(window, "archive_preview_request_id", 0) or 0)
            context["archive_isolated_package_request_id"] = int(
                getattr(window, "archive_isolated_package_request_id", 0) or 0
            )
            context["pending_archive_preview_request"] = str(getattr(window, "pending_archive_preview_request", None))
            context["scheduled_archive_preview_request"] = str(getattr(window, "scheduled_archive_preview_request", None))
            context["active_d3d11_package"] = str(getattr(window, "archive_isolated_renderer_active_package", "") or "")
            status_file = getattr(window, "archive_isolated_renderer_status_file", None)
            context["d3d11_status_file"] = str(status_file or "")
            if status_file is not None and Path(status_file).is_file():
                try:
                    status_payload = json.loads(Path(status_file).read_text(encoding="utf-8"))
                except Exception as exc:
                    status_payload = {"read_error": str(exc)}
                context["d3d11_status_payload"] = status_payload
            process = getattr(window, "archive_isolated_renderer_process", None)
            if process is not None:
                try:
                    context["d3d11_process_pid"] = int(process.processId())
                except RuntimeError:
                    context["d3d11_process_pid"] = "deleted"
                d3d11_process_memory = _windows_process_memory_snapshot(context.get("d3d11_process_pid", 0))
                if d3d11_process_memory:
                    context["d3d11_process_memory"] = d3d11_process_memory
                try:
                    context["d3d11_process_state"] = str(process.state())
                except RuntimeError:
                    context["d3d11_process_state"] = "deleted"
            package_worker = getattr(window, "archive_isolated_package_worker", None)
            package_thread = getattr(window, "archive_isolated_package_thread", None)
            context["archive_isolated_package_worker_active"] = package_worker is not None
            if package_thread is not None:
                try:
                    context["archive_isolated_package_thread_running"] = bool(package_thread.isRunning())
                except RuntimeError:
                    context["archive_isolated_package_thread_running"] = "deleted"
            preview_worker = getattr(window, "archive_preview_worker", None)
            preview_thread = getattr(window, "archive_preview_thread", None)
            context["archive_preview_worker_active"] = preview_worker is not None
            if preview_thread is not None:
                try:
                    context["archive_preview_thread_running"] = bool(preview_thread.isRunning())
                except RuntimeError:
                    context["archive_preview_thread_running"] = "deleted"
        except Exception:
            pass
        _add_persisted_crash_breadcrumbs(context)
        try:
            log_lines = window.log_view.toPlainText().splitlines()
            context["recent_log_tail"] = log_lines[-80:]
        except Exception:
            pass
        try:
            archive_log_lines = window.archive_log_view.toPlainText().splitlines()
            context["recent_archive_log_tail"] = archive_log_lines[-80:]
        except Exception:
            pass
        _cached_crash_context = dict(context)
        return context

    def _process_is_alive(pid_value: object) -> bool:
        try:
            pid = int(pid_value)
        except (TypeError, ValueError):
            return False
        if pid <= 0 or pid == os.getpid():
            return False
        if platform.system().lower() != "windows":
            try:
                os.kill(pid, 0)
                return True
            except OSError:
                return False
        try:
            process_query_limited_information = 0x1000
            still_active = 259
            handle = ctypes.windll.kernel32.OpenProcess(process_query_limited_information, False, pid)
            if not handle:
                return False
            exit_code = ctypes.c_ulong()
            try:
                if not ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                    return False
                return int(exit_code.value) == still_active
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        except Exception:
            return False

    def _write_crash_report(
        kind: str,
        title: str,
        body: str,
        *,
        context: Optional[Dict[str, object]] = None,
        force: bool = False,
    ) -> None:
        if not force and not _capture_crash_details_enabled and kind not in {
            "unhandled_exception",
            "thread_exception",
            "unraisable_exception",
            "startup_failure",
            "previous_session_unclean_exit",
            "app_hang_detected",
            "native_fault_log",
        }:
            return
        try:
            crash_reports_dir.mkdir(parents=True, exist_ok=True)
            report_path = crash_reports_dir / f"{kind}_{_crash_timestamp()}_{os.getpid()}.log"
            lines = [
                f"{APP_TITLE} crash/details report",
                f"Kind: {kind}",
                f"Time: {time.strftime('%Y-%m-%d %H:%M:%S')}",
                f"Version: {APP_VERSION}",
                f"Process ID: {os.getpid()}",
                f"Session ID: {_session_id}",
                f"Python: {sys.version}",
                f"Platform: {platform.platform()}",
                "",
                title.strip(),
                "",
                body.rstrip(),
            ]
            report_context = context if context is not None else _collect_crash_context()
            if report_context:
                lines.extend(["", "Context:", json.dumps(report_context, indent=2, ensure_ascii=False)])
            report_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        except Exception:
            pass

    def _format_thread_dump() -> str:
        frames = sys._current_frames()
        thread_names = {thread.ident: thread.name for thread in threading.enumerate()}
        parts: List[str] = []
        for thread_id, frame in sorted(frames.items(), key=lambda item: str(thread_names.get(item[0], item[0]))):
            parts.append(f"\n--- Thread {thread_names.get(thread_id, 'unknown')} ({thread_id}) ---")
            parts.extend(traceback.format_stack(frame))
        return "".join(parts).strip()

    def _heartbeat_payload(phase: str, *, clean_shutdown: bool = False) -> Dict[str, object]:
        return {
            "app": APP_TITLE,
            "version": APP_VERSION,
            "pid": os.getpid(),
            "session_id": _session_id,
            "phase": str(phase or "running"),
            "clean_shutdown": bool(clean_shutdown),
            "started_at": _session_id.split("-", 1)[-1],
            "last_beat_epoch": time.time(),
            "last_beat": time.strftime("%Y-%m-%d %H:%M:%S"),
            "platform": platform.platform(),
        }

    def _write_heartbeat(phase: str = "", *, clean_shutdown: bool = False) -> None:
        nonlocal _heartbeat_phase, _last_heartbeat_written_at
        try:
            if phase:
                _heartbeat_phase = str(phase)
            crash_reports_dir.mkdir(parents=True, exist_ok=True)
            payload = _heartbeat_payload(_heartbeat_phase, clean_shutdown=clean_shutdown)
            temp_path = heartbeat_path.with_suffix(".tmp")
            temp_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
            temp_path.replace(heartbeat_path)
            with _heartbeat_lock:
                _last_heartbeat_written_at = float(payload["last_beat_epoch"])
        except Exception:
            pass

    def _check_previous_unclean_exit() -> bool:
        try:
            if not heartbeat_path.is_file():
                return False
            payload = json.loads(heartbeat_path.read_text(encoding="utf-8"))
            if bool(payload.get("clean_shutdown")):
                return False
            if str(payload.get("session_id") or "") == _session_id:
                return False
            last_beat = float(payload.get("last_beat_epoch") or 0.0)
            age_s = max(0.0, time.time() - last_beat) if last_beat > 0 else 0.0
            previous_pid_alive = _process_is_alive(payload.get("pid"))
            if age_s < 20.0 and previous_pid_alive:
                return False
            previous_context: Dict[str, object] = {
                "previous_heartbeat": payload,
                "heartbeat_age_seconds": round(age_s, 3),
                "previous_pid_alive": previous_pid_alive,
            }
            _add_persisted_crash_breadcrumbs(previous_context)
            _write_crash_report(
                "previous_session_unclean_exit",
                "Previous session did not shut down cleanly",
                (
                    "The previous app session left an active heartbeat file. "
                    "This usually means the process crashed, froze and was force-closed, or Windows terminated it."
                ),
                context=previous_context,
                force=True,
            )
            return True
        except Exception as exc:
            _write_crash_report(
                "previous_session_heartbeat_read_error",
                "Could not inspect previous heartbeat",
                str(exc),
                force=True,
            )
            return False

    def _start_heartbeat_timer(app: QApplication) -> QTimer:
        timer = QTimer(app)
        timer.setInterval(5000)
        timer.timeout.connect(_write_heartbeat)
        timer.start()
        return timer

    def _start_hang_watchdog() -> threading.Thread:
        def _watchdog() -> None:
            reported_stale = False
            while not _heartbeat_stop_event.wait(10.0):
                with _heartbeat_lock:
                    age_s = time.time() - _last_heartbeat_written_at
                if age_s >= 45.0 and not reported_stale:
                    reported_stale = True
                    _write_crash_report(
                        "app_hang_detected",
                        "GUI heartbeat stalled",
                        (
                            f"The GUI heartbeat has not advanced for {age_s:.1f} seconds. "
                            "If the app later recovered, this report still marks the stall point."
                        ),
                        context={
                            "heartbeat_age_seconds": round(age_s, 3),
                            "thread_dump": _format_thread_dump(),
                        },
                        force=True,
                    )
                elif age_s < 15.0:
                    reported_stale = False

        thread = threading.Thread(target=_watchdog, name="cdmw-hang-watchdog", daemon=True)
        thread.start()
        return thread

    def _enable_native_fault_log() -> None:
        nonlocal _fault_log_handle
        try:
            crash_reports_dir.mkdir(parents=True, exist_ok=True)
            _fault_log_handle = (crash_reports_dir / "native_fault_current.log").open("a", encoding="utf-8")
            _fault_log_handle.write(
                f"\n\n=== {APP_TITLE} native fault log session {_session_id} {time.strftime('%Y-%m-%d %H:%M:%S')} ===\n"
            )
            _fault_log_handle.flush()
            faulthandler.enable(file=_fault_log_handle, all_threads=True)
        except Exception:
            _fault_log_handle = None

    def _handle_uncaught_exception(exc_type, exc_value, exc_traceback) -> None:
        formatted = "".join(traceback.format_exception(exc_type, exc_value, exc_traceback))
        _write_crash_report("unhandled_exception", "Unhandled exception", formatted, force=True)
        _default_sys_excepthook(exc_type, exc_value, exc_traceback)

    def _handle_thread_exception(args) -> None:
        formatted = "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))
        thread_name = getattr(getattr(args, "thread", None), "name", "unknown thread")
        _write_crash_report("thread_exception", f"Unhandled thread exception in {thread_name}", formatted, force=True)
        if _default_threading_excepthook is not None:
            _default_threading_excepthook(args)

    def _handle_unraisable_exception(args) -> None:
        formatted = "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))
        _write_crash_report(
            "unraisable_exception",
            f"Unraisable exception from {getattr(args, 'object', None)!r}",
            formatted,
            force=True,
        )
        if _default_unraisablehook is not None:
            _default_unraisablehook(args)

    def _timing_value(timings: Optional[Dict[str, float]], key: str) -> float:
        if not timings:
            return 0.0
        raw_value = timings.get(key, 0.0)
        try:
            return max(0.0, float(raw_value))
        except (TypeError, ValueError):
            return 0.0

    def _merge_timing_maps(*timing_maps: Optional[Dict[str, float]]) -> Dict[str, float]:
        merged: Dict[str, float] = {}
        for timing_map in timing_maps:
            if not timing_map:
                continue
            for key, value in timing_map.items():
                try:
                    merged[str(key)] = max(0.0, float(value))
                except (TypeError, ValueError):
                    continue
        return merged

    def _format_timing_summary(
        prefix: str,
        source: str,
        timings: Optional[Dict[str, float]],
        ordered_fields: Sequence[Tuple[str, str]],
    ) -> str:
        parts = [prefix, f"source={str(source or '').strip() or 'unknown'}"]
        for key, label in ordered_fields:
            parts.append(f"{label}={_timing_value(timings, key):.2f}s")
        return " | ".join(parts)

    def _is_expected_cancellation_message(message: object) -> bool:
        text = str(message or "")
        return "Processing stopped by user." in text or "stopped by user" in text.lower() or "cancelled by user" in text.lower()

    sys.excepthook = _handle_uncaught_exception
    if _default_threading_excepthook is not None:
        threading.excepthook = _handle_thread_exception
    if _default_unraisablehook is not None:
        sys.unraisablehook = _handle_unraisable_exception
    _enable_native_fault_log()
    _previous_session_unclean = _check_previous_unclean_exit()
    _record_runtime_event(
        "session_start",
        crash_reports_dir=str(crash_reports_dir),
        previous_session_unclean=bool(_previous_session_unclean),
    )
    _write_heartbeat("starting")
    _start_hang_watchdog()

    def create_settings() -> QSettings:
        settings_file_path.parent.mkdir(parents=True, exist_ok=True)
        configure_texture_classification_registry(
            settings_file_path.parent / "texture_classification_registry.json"
        )
        legacy_settings_candidates = [settings_file_path.with_name(f"{name}.cfg") for name in LEGACY_APP_NAMES]
        if not settings_file_path.exists():
            for legacy_settings_path in legacy_settings_candidates:
                if not legacy_settings_path.exists():
                    continue
                try:
                    shutil.copy2(legacy_settings_path, settings_file_path)
                    break
                except OSError:
                    continue
        settings = QSettings(str(settings_file_path), QSettings.Format.IniFormat)
        settings.setFallbacksEnabled(False)
        return settings

    def iter_app_icon_candidate_paths() -> Tuple[Path, ...]:
        search_roots: List[Path] = []

        def add_root(root: Optional[Path]) -> None:
            if root is None:
                return
            try:
                normalized = root.resolve()
            except OSError:
                normalized = root
            if normalized not in search_roots:
                search_roots.append(normalized)

        if getattr(sys, "frozen", False):
            meipass = getattr(sys, "_MEIPASS", None)
            if meipass:
                add_root(Path(str(meipass)))
            executable_dir = Path(sys.executable).resolve().parent
            add_root(executable_dir)
            add_root(executable_dir / "_internal")
        add_root(Path(__file__).resolve().parents[2])
        add_root(Path.cwd())

        relative_candidates = (
            Path("assets") / "cdmw.ico",
            Path("assets") / "cdmw.png",
            Path("_internal") / "assets" / "cdmw.ico",
            Path("_internal") / "assets" / "cdmw.png",
            Path("cdmw.ico"),
            Path("cdmw.png"),
        )
        candidates: List[Path] = []
        seen: set[str] = set()
        for root in search_roots:
            for relative_path in relative_candidates:
                candidate = root / relative_path
                candidate_key = str(candidate).casefold()
                if candidate_key in seen:
                    continue
                seen.add(candidate_key)
                candidates.append(candidate)
        return tuple(candidates)

    def resolve_app_icon_path() -> Optional[Path]:
        for candidate in iter_app_icon_candidate_paths():
            if candidate.is_file():
                return candidate
        return None

    def load_app_icon() -> Tuple[QIcon, Optional[Path]]:
        for candidate in iter_app_icon_candidate_paths():
            if not candidate.is_file():
                continue
            icon = QIcon(str(candidate))
            if not icon.isNull():
                return icon, candidate
        return QIcon(), None

    def expand_tree_columns_to_available_width(tree: QTreeWidget) -> None:
        if not isinstance(tree, QTreeWidget):
            return
        try:
            if bool(tree.property("cdmw_disable_auto_column_fill")):
                return
        except Exception:
            return
        header = tree.header()
        if header is None:
            return
        count = header.count()
        if count <= 0:
            return
        try:
            visible_columns = [column for column in range(count) if not header.isSectionHidden(column)]
            viewport_width = int(tree.viewport().width())
        except Exception:
            return
        if not visible_columns or viewport_width <= 0:
            return
        current_widths = [max(1, int(header.sectionSize(column))) for column in visible_columns]
        total_width = sum(current_widths)
        extra_width = viewport_width - total_width - 2
        if extra_width <= max(12, len(visible_columns) * 3):
            return
        weight_total = max(1, total_width)
        remaining = extra_width
        for index, column in enumerate(visible_columns):
            if index == len(visible_columns) - 1:
                add_width = remaining
            else:
                add_width = max(1, int(round(extra_width * (current_widths[index] / weight_total))))
                remaining -= add_width
            if add_width <= 0:
                continue
            try:
                header.resizeSection(column, int(header.sectionSize(column)) + add_width)
            except Exception:
                pass

    class AutoTreeColumnWidthEventFilter(QObject):
        def eventFilter(self, watched: QObject, event: QEvent) -> bool:  # type: ignore[override]
            if event.type() in (QEvent.Type.Show, QEvent.Type.Resize, QEvent.Type.LayoutRequest) and isinstance(watched, QTreeWidget):
                QTimer.singleShot(0, lambda tree=watched: expand_tree_columns_to_available_width(tree))
            return False

    class TreeHorizontalWheelGuard(QObject):
        def __init__(self, tree: QTreeWidget) -> None:
            super().__init__(tree)
            self._tree = tree

        def eventFilter(self, watched: QObject, event: QEvent) -> bool:  # type: ignore[override]
            if event.type() != QEvent.Type.Wheel:
                return False
            tree = self._tree
            try:
                horizontal_bar = tree.horizontalScrollBar()
                previous_value = int(horizontal_bar.value())
                pixel_delta = event.pixelDelta()  # type: ignore[attr-defined]
                angle_delta = event.angleDelta()  # type: ignore[attr-defined]
                has_horizontal_delta = int(pixel_delta.x()) != 0 or int(angle_delta.x()) != 0
                has_vertical_delta = int(pixel_delta.y()) != 0 or int(angle_delta.y()) != 0
                modifiers = event.modifiers()  # type: ignore[attr-defined]
            except Exception:
                return False
            if not has_horizontal_delta or modifiers & Qt.ShiftModifier:
                return False
            if not has_vertical_delta:
                return True

            def _restore_horizontal_scroll() -> None:
                try:
                    horizontal_bar.setValue(max(horizontal_bar.minimum(), min(previous_value, horizontal_bar.maximum())))
                except RuntimeError:
                    pass

            QTimer.singleShot(0, _restore_horizontal_scroll)
            return False

    class AppWindowIconEventFilter(QObject):
        def __init__(self, app_icon: QIcon, parent: Optional[QObject] = None) -> None:
            super().__init__(parent)
            self._app_icon = QIcon(app_icon)

        def eventFilter(self, watched: QObject, event: QEvent) -> bool:  # type: ignore[override]
            if (
                event.type() in (QEvent.Type.Show, QEvent.Type.WindowActivate)
                and isinstance(watched, QWidget)
                and watched.isWindow()
                and not self._app_icon.isNull()
            ):
                try:
                    watched.setWindowIcon(self._app_icon)
                except RuntimeError:
                    pass
            return False

    def apply_windows_app_user_model_id() -> None:
        if os.name != "nt":
            return
        try:
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(f"{APP_ORGANIZATION}.{APP_NAME}")
        except Exception:
            pass

    def _read_int_setting(settings: QSettings, key: str, default: int) -> int:
        try:
            return int(settings.value(key, default))
        except (TypeError, ValueError):
            return int(default)

    def _read_bool_setting(settings: QSettings, key: str, default: bool) -> bool:
        value = settings.value(key, default)
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in {"1", "true", "yes", "on"}

    def _responsive_control_scale_for_resolution(screen_width: int, screen_height: int) -> float:
        if screen_width <= 1366:
            width_scale = 0.78
        elif screen_width <= 1600:
            width_scale = 0.84
        elif screen_width <= 1920:
            width_scale = 0.90
        elif screen_width <= 2560:
            width_scale = 0.96
        else:
            width_scale = 1.0
        if screen_height <= 768:
            height_scale = 0.78
        elif screen_height <= 900:
            height_scale = 0.84
        elif screen_height <= 1080:
            height_scale = 0.90
        elif screen_height <= 1200:
            height_scale = 0.94
        else:
            height_scale = 1.0
        return min(width_scale, height_scale)

    def _responsive_control_scale_for_width(screen_width: int) -> float:
        fallback_height = 1080 if screen_width <= 1920 else 1440
        return _responsive_control_scale_for_resolution(screen_width, fallback_height)

    def apply_app_theme(
        app: QApplication,
        settings: QSettings,
        theme_key: str,
        *,
        screen_width: Optional[int] = None,
        screen_height: Optional[int] = None,
    ) -> str:
        resolved_theme = theme_key if theme_key in UI_THEME_SCHEMES else DEFAULT_UI_THEME
        ui_font_family = str(settings.value("appearance/ui_font_family", DEFAULT_UI_FONT_FAMILY) or DEFAULT_UI_FONT_FAMILY)
        configured_base_font_size = max(
            UI_FONT_SIZE_MIN,
            min(UI_FONT_SIZE_MAX, _read_int_setting(settings, "appearance/ui_font_size", DEFAULT_UI_FONT_SIZE)),
        )
        configured_data_font_size = max(
            UI_FONT_SIZE_MIN,
            min(UI_FONT_SIZE_MAX, _read_int_setting(settings, "appearance/data_font_size", DEFAULT_UI_DATA_FONT_SIZE)),
        )
        fallback_width, fallback_height = available_screen_size_for(None)
        effective_screen_width = int(screen_width or fallback_width)
        effective_screen_height = int(screen_height or fallback_height)
        screen_scale = _responsive_control_scale_for_resolution(effective_screen_width, effective_screen_height)
        base_font_size = max(UI_FONT_SIZE_MIN, min(UI_FONT_SIZE_MAX, int(round(configured_base_font_size * screen_scale))))
        data_font_size = max(UI_FONT_SIZE_MIN, min(UI_FONT_SIZE_MAX, int(round(configured_data_font_size * screen_scale))))
        density_key = str(settings.value("appearance/ui_density", DEFAULT_UI_DENSITY) or DEFAULT_UI_DENSITY)
        effective_density_key = "compact" if screen_scale < 0.94 else density_key
        app_font = QFont(app.font())
        app_font.setFamily(ui_font_family)
        app_font.setPointSize(base_font_size)
        app.setFont(app_font)
        app.setPalette(build_app_palette(resolved_theme))
        app.setStyleSheet(
            build_app_stylesheet(
                resolved_theme,
                base_font_size=base_font_size,
                data_font_size=data_font_size,
                density_key=effective_density_key,
                layout_scale=screen_scale,
            )
        )
        return resolved_theme

    def build_monospace_font(settings: QSettings) -> QFont:
        point_size = _read_int_setting(settings, "appearance/log_font_size", DEFAULT_UI_LOG_FONT_SIZE)
        selected_family = str(
            settings.value("appearance/log_font_family", DEFAULT_UI_LOG_FONT_FAMILY) or DEFAULT_UI_LOG_FONT_FAMILY
        )
        bold_enabled = _read_bool_setting(settings, "appearance/log_font_bold", DEFAULT_UI_LOG_FONT_BOLD)
        fallback_order = [selected_family] + [family for family in LOG_FONT_FAMILY_OPTIONS if family != selected_family]
        font = QFont(fallback_order[0])
        for family in fallback_order:
            candidate = QFont(family)
            if candidate.exactMatch():
                font = candidate
                break
        font.setStyleHint(QFont.Monospace)
        font.setPointSize(point_size)
        font.setBold(bold_enabled)
        return font

    def read_log_text_style(settings: QSettings) -> str:
        value = str(
            settings.value("appearance/log_text_style", DEFAULT_UI_LOG_TEXT_STYLE)
            or DEFAULT_UI_LOG_TEXT_STYLE
        ).strip().lower()
        allowed = {key for key, _label in UI_LOG_TEXT_STYLE_OPTIONS}
        return value if value in allowed else DEFAULT_UI_LOG_TEXT_STYLE

    def read_text_color_scheme(settings: QSettings, key: str, default: str) -> str:
        value = str(settings.value(key, default) or default).strip().lower()
        allowed = {scheme_key for scheme_key, _label in UI_TEXT_COLOR_SCHEME_OPTIONS}
        return value if value in allowed else default

    def apply_window_text_highlight_style(window: "MainWindow") -> None:
        style = read_log_text_style(window.settings)
        log_scheme = read_text_color_scheme(
            window.settings,
            "appearance/log_color_scheme",
            DEFAULT_UI_LOG_COLOR_SCHEME,
        )
        preview_scheme = read_text_color_scheme(
            window.settings,
            "appearance/preview_color_scheme",
            DEFAULT_UI_PREVIEW_COLOR_SCHEME,
        )
        for highlighter in (
            window.log_highlighter,
            window.archive_log_highlighter,
            window.text_search_tab.log_highlighter,
        ):
            if hasattr(highlighter, "set_highlight_style"):
                highlighter.set_highlight_style(style)
            if hasattr(highlighter, "set_color_scheme"):
                highlighter.set_color_scheme(log_scheme)
        for editor in (
            window.archive_preview_text_edit,
            window.archive_preview_info_edit,
            window.archive_preview_details_edit,
            window.text_search_tab.preview_text_edit,
        ):
            if hasattr(editor, "set_highlight_style"):
                editor.set_highlight_style(style)
            if hasattr(editor, "set_color_scheme"):
                editor.set_color_scheme(preview_scheme)

    def apply_window_data_fonts(window: "MainWindow") -> None:
        log_font = build_monospace_font(window.settings)
        window.log_view.setFont(log_font)
        window.log_view.document().setDefaultFont(log_font)
        window.archive_log_view.setFont(log_font)
        window.archive_log_view.document().setDefaultFont(log_font)
        window.archive_preview_text_edit.apply_font_preferences(log_font, preserve_size=False)
        window.archive_preview_info_edit.apply_font_preferences(log_font, preserve_size=False)
        window.archive_preview_details_edit.apply_font_preferences(log_font, preserve_size=False)
        window.text_search_tab.log_view.setFont(log_font)
        window.text_search_tab.log_view.document().setDefaultFont(log_font)
        window.text_search_tab.preview_text_edit.apply_font_preferences(log_font, preserve_size=False)
        window.replace_assistant_tab.log_view.setFont(log_font)
        window.replace_assistant_tab.log_view.document().setDefaultFont(log_font)
        window.replace_assistant_tab.preview_details_edit.setFont(log_font)
        window.replace_assistant_tab.preview_details_edit.document().setDefaultFont(log_font)
        bold_enabled = _read_bool_setting(window.settings, "appearance/log_font_bold", DEFAULT_UI_LOG_FONT_BOLD)
        window.log_highlighter.set_bold_enabled(bold_enabled)
        window.archive_log_highlighter.set_bold_enabled(bold_enabled)
        window.text_search_tab.log_highlighter.set_bold_enabled(bold_enabled)
        apply_window_text_highlight_style(window)

    class ScanWorker(QObject):
        log_message = Signal(str)
        result_ready = Signal(int)
        error = Signal(str)
        finished = Signal()

        def __init__(self, config: AppConfig):
            super().__init__()
            self.config = config
            self.stop_event = threading.Event()

        def stop(self) -> None:
            self.stop_event.set()

        @Slot()
        def run(self) -> None:
            try:
                self.log_message.emit("Scanning DDS files...")
                result = scan_dds_files(self.config, stop_event=self.stop_event)
                self.result_ready.emit(result.total_files)
                self.log_message.emit(f"Scan complete. Found {result.total_files} DDS files.")
            except Exception as exc:
                self.error.emit(str(exc))
            finally:
                self.finished.emit()

    class ArchiveScanWorker(QObject):
        log_message = Signal(str)
        progress_changed = Signal(int, int, str)
        completed = Signal(object)
        error = Signal(str)
        finished = Signal()

        def __init__(
            self,
            package_root: Path,
            cache_root: Path,
            *,
            force_refresh: bool = False,
            build_tree_index: bool = True,
            filter_text: str = "",
            exclude_filter_text: str = "",
            extension_filter: str = "*",
            package_filter_text: str = "",
            structure_filter: str = "",
            role_filter: str = "all",
            exclude_common_technical_suffixes: bool = False,
            min_size_kb: int = 0,
            previewable_only: bool = False,
            build_category_index: bool = True,
            item_search_aliases: Optional[Mapping[str, str]] = None,
            sort_column: int = -1,
            sort_order: str = "asc",
            game_executable_fingerprints: Optional[Mapping[str, Mapping[str, object]]] = None,
            crash_reports_dir: Optional[Path] = None,
        ):
            super().__init__()
            self.package_root = package_root
            self.cache_root = cache_root
            self.force_refresh = force_refresh
            self.build_tree_index = build_tree_index
            self.filter_text = filter_text
            self.exclude_filter_text = exclude_filter_text
            self.extension_filter = extension_filter
            self.package_filter_text = package_filter_text
            self.structure_filter = structure_filter
            self.role_filter = role_filter
            self.exclude_common_technical_suffixes = exclude_common_technical_suffixes
            self.min_size_kb = min_size_kb
            self.previewable_only = previewable_only
            self.build_category_index = build_category_index
            self.item_search_aliases = dict(item_search_aliases or {})
            self.sort_column = normalize_archive_browser_sort_column(sort_column)
            self.sort_order = normalize_archive_browser_sort_order(sort_order)
            self.crash_reports_dir = crash_reports_dir
            self.game_executable_fingerprints = {
                str(key): dict(value)
                for key, value in (game_executable_fingerprints or {}).items()
                if isinstance(value, Mapping)
            }
            self.updated_game_executable_fingerprints: Optional[Dict[str, Dict[str, object]]] = None
            self.stop_event = threading.Event()

        def stop(self) -> None:
            self.stop_event.set()

        def _write_scan_breadcrumb(self, payload: Mapping[str, object]) -> None:
            if self.crash_reports_dir is None:
                return
            try:
                self.crash_reports_dir.mkdir(parents=True, exist_ok=True)
                breadcrumb_path = self.crash_reports_dir / "archive_scan_breadcrumb.json"
                enriched = dict(payload)
                enriched.setdefault("worker", "ArchiveScanWorker")
                enriched.setdefault("pid", os.getpid())
                temp_path = breadcrumb_path.with_suffix(".tmp")
                temp_path.write_text(json.dumps(enriched, indent=2), encoding="utf-8")
                temp_path.replace(breadcrumb_path)
            except Exception:
                pass

        def _check_game_update_and_invalidate_archive_cache(self) -> None:
            executable_path = resolve_crimson_desert_executable(self.package_root)
            if executable_path is None:
                return

            try:
                stat_result = executable_path.stat()
            except OSError as exc:
                self.log_message.emit(f"Game update check skipped: could not read {executable_path}: {exc}")
                return

            executable_key = str(executable_path).strip().lower()
            current_size = int(stat_result.st_size)
            current_mtime_ns = int(getattr(stat_result, "st_mtime_ns", int(stat_result.st_mtime * 1_000_000_000)))
            records: Dict[str, Dict[str, object]] = {
                str(key): dict(value)
                for key, value in self.game_executable_fingerprints.items()
                if isinstance(value, Mapping)
            }
            previous_record = records.get(executable_key, {})
            previous_hash = str(previous_record.get("sha256", "") or "").strip()
            previous_size = int(previous_record.get("size", -1) or -1)
            previous_mtime_ns = int(previous_record.get("mtime_ns", -1) or -1)

            if previous_hash and previous_size == current_size and previous_mtime_ns == current_mtime_ns:
                return

            try:
                current_hash = sha256_file(executable_path)
            except OSError as exc:
                self.log_message.emit(f"Game update check skipped: could not hash {executable_path}: {exc}")
                return

            records[executable_key] = {
                "path": str(executable_path),
                "sha256": current_hash,
                "size": current_size,
                "mtime_ns": current_mtime_ns,
                "checked_at": time.time(),
            }
            self.updated_game_executable_fingerprints = records

            if not previous_hash:
                self.log_message.emit(f"Recorded CrimsonDesert.exe hash baseline: {executable_path}")
                return
            if previous_hash == current_hash:
                return

            deleted_paths = invalidate_archive_browser_cache(
                self.package_root,
                self.cache_root,
                on_log=self.log_message.emit,
            )
            if deleted_paths:
                self.log_message.emit(
                    "Game update detected via CrimsonDesert.exe hash. "
                    f"Archive Browser cache invalidated ({len(deleted_paths):,} file(s))."
                )
            else:
                self.log_message.emit(
                    "Game update detected via CrimsonDesert.exe hash. No existing Archive Browser cache file needed deletion."
                )

        @Slot()
        def run(self) -> None:
            gc_was_enabled = gc.isenabled()
            if gc_was_enabled:
                gc.disable()
            try:
                timings: Dict[str, float] = {}
                started_at = time.perf_counter()
                if self.force_refresh:
                    self.log_message.emit(f"Refreshing archive packages under {self.package_root}")
                else:
                    self.log_message.emit(f"Loading archive packages under {self.package_root}")
                game_update_started_at = time.perf_counter()
                self._check_game_update_and_invalidate_archive_cache()
                timings["game_update_check_s"] = max(0.0, float(time.perf_counter() - game_update_started_at))
                entries, source, cache_path, scan_timings = scan_archive_entries_cached(
                    self.package_root,
                    self.cache_root,
                    force_refresh=self.force_refresh,
                    on_log=self.log_message.emit,
                    on_progress=self.progress_changed.emit,
                    on_breadcrumb=self._write_scan_breadcrumb,
                    stop_event=self.stop_event,
                )
                timings.update(scan_timings)
                item_search_aliases: Dict[str, str] = {}
                item_display_names: Dict[str, str] = {}
                item_exact_display_names: Dict[str, str] = {}
                item_related_display_names: Dict[str, str] = {}
                item_asset_catalog: List[Dict[str, object]] = []
                path_index: Dict[str, List[ArchiveEntry]] = {}
                basename_index: Dict[str, List[ArchiveEntry]] = {}
                extension_index: Dict[str, List[ArchiveEntry]] = {}
                name_search_index: Optional[ArchiveNameSearchIndex] = None
                derived_cache = None
                derived_cache_needs_write = False
                if entries and not self.force_refresh:
                    self.log_message.emit("Checking archive derived index cache...")
                    self.progress_changed.emit(0, 0, "Checking archive derived index cache...")
                    derived_cache = load_archive_derived_index_cache(
                        self.package_root,
                        self.cache_root,
                        entries,
                        on_log=self.log_message.emit,
                        timings=timings,
                    )
                if isinstance(derived_cache, dict):
                    item_search_aliases = dict(derived_cache.get("item_search_aliases", {}) or {})
                    item_display_names = dict(derived_cache.get("item_display_names", {}) or {})
                    item_exact_display_names = dict(derived_cache.get("item_exact_display_names", {}) or {})
                    item_related_display_names = dict(derived_cache.get("item_related_display_names", {}) or {})
                    item_asset_catalog = [
                        dict(row)
                        for row in (derived_cache.get("item_asset_catalog", []) or [])
                        if isinstance(row, Mapping)
                    ]
                    cached_name_search_index = derived_cache.get("name_search_index")
                    if isinstance(cached_name_search_index, ArchiveNameSearchIndex):
                        name_search_index = cached_name_search_index
                    else:
                        derived_cache_needs_write = bool(entries)
                    timings.setdefault("item_search_index_s", 0.0)
                else:
                    derived_cache_needs_write = bool(entries)
                    self.log_message.emit("Building item-name search index...")
                    self.progress_changed.emit(0, 0, "Building item-name search index...")
                    item_index_started_at = time.perf_counter()
                    try:
                        item_index = build_archive_item_search_index(
                            entries,
                            on_log=self.log_message.emit,
                            stop_event=self.stop_event,
                        )
                        item_search_aliases = dict(item_index.model_base_aliases)
                        item_display_names = dict(getattr(item_index, "model_base_display_names", {}) or {})
                        item_exact_display_names = dict(getattr(item_index, "model_base_exact_display_names", {}) or {})
                        item_related_display_names = dict(getattr(item_index, "model_base_related_display_names", {}) or {})
                        item_asset_catalog = [
                            row.to_cache_dict()
                            for row in getattr(item_index, "asset_catalog", [])
                            if hasattr(row, "to_cache_dict")
                        ]
                    except RunCancelled:
                        raise
                    except Exception as exc:
                        self.log_message.emit(f"Warning: item-name search index unavailable: {exc}")
                    timings["item_search_index_s"] = max(0.0, float(time.perf_counter() - item_index_started_at))
                self.log_message.emit("Building archive path lookup index...")
                self.progress_changed.emit(0, 0, "Building archive path lookup index...")
                path_index_started_at = time.perf_counter()
                path_index = build_archive_entry_path_index(entries)
                timings["entry_path_index_s"] = max(0.0, float(time.perf_counter() - path_index_started_at))
                self.log_message.emit("Building archive basename lookup index...")
                self.progress_changed.emit(0, 0, "Building archive basename lookup index...")
                basename_index_started_at = time.perf_counter()
                basename_index = build_archive_entry_basename_index(entries)
                timings["entry_basename_index_s"] = max(0.0, float(time.perf_counter() - basename_index_started_at))
                self.log_message.emit("Building archive extension lookup index...")
                self.progress_changed.emit(0, 0, "Building archive extension lookup index...")
                extension_index_started_at = time.perf_counter()
                extension_index = build_archive_entry_extension_index(entries)
                timings["entry_extension_index_s"] = max(0.0, float(time.perf_counter() - extension_index_started_at))
                if name_search_index is None:
                    self.log_message.emit("Building archive name search index...")
                    self.progress_changed.emit(0, 0, "Building archive name search index...")
                    name_search_index_started_at = time.perf_counter()
                    name_search_index = build_archive_name_search_index(
                        entries,
                        item_search_aliases=item_search_aliases,
                        on_progress=self.progress_changed.emit,
                        stop_event=self.stop_event,
                    )
                    timings["entry_name_search_index_s"] = max(0.0, float(time.perf_counter() - name_search_index_started_at))
                else:
                    self.log_message.emit("Loaded archive name search index from derived cache.")
                    timings["entry_name_search_index_s"] = 0.0
                self.log_message.emit("Preparing archive browser state from loaded entries...")
                self.progress_changed.emit(0, 0, "Preparing archive browser state from loaded entries...")
                browser_state_started_at = time.perf_counter()
                browser_state = prepare_archive_browser_state(
                    entries,
                    filter_text=self.filter_text,
                    exclude_filter_text=self.exclude_filter_text,
                    extension_filter=self.extension_filter,
                    package_filter_text=self.package_filter_text,
                    structure_filter=self.structure_filter,
                    role_filter=self.role_filter,
                    exclude_common_technical_suffixes=self.exclude_common_technical_suffixes,
                    min_size_kb=self.min_size_kb,
                    previewable_only=self.previewable_only,
                    item_search_aliases=item_search_aliases,
                    archive_entries_by_basename=basename_index,
                    archive_entries_by_normalized_path=path_index,
                    archive_name_search_index=name_search_index,
                    build_structure_children=True,
                    build_tree_index=self.build_tree_index,
                    sort_column=self.sort_column,
                    sort_order=self.sort_order,
                    item_display_names=item_display_names,
                    item_exact_display_names=item_exact_display_names,
                    item_related_display_names=item_related_display_names,
                    on_progress=self.progress_changed.emit,
                    stop_event=self.stop_event,
                )
                timings["browser_state_s"] = max(0.0, float(time.perf_counter() - browser_state_started_at))
                if self.build_category_index:
                    self.log_message.emit("Building archive category index...")
                    self.progress_changed.emit(0, 0, "Building archive category index...")
                    category_index_started_at = time.perf_counter()
                    browser_state["category_entry_indexes"] = build_archive_category_entry_index(
                        browser_state.get("filtered_entries", ()),
                        on_progress=self.progress_changed.emit,
                        stop_event=self.stop_event,
                    )
                    timings["category_index_s"] = max(0.0, float(time.perf_counter() - category_index_started_at))
                else:
                    browser_state["category_entry_indexes"] = {}
                    timings["category_index_s"] = 0.0
                timings["total_s"] = max(0.0, float(time.perf_counter() - started_at))
                timing_summary = _format_timing_summary(
                    "Archive scan timings",
                    source,
                    timings,
                    (
                        ("game_update_check_s", "game_update"),
                        ("cache_check_s", "cache_check"),
                        ("cache_load_s", "cache_load"),
                        ("archive_scan_s", "archive_scan"),
                        ("cache_write_s", "cache_write"),
                        ("derived_cache_check_s", "derived_check"),
                        ("derived_cache_load_s", "derived_load"),
                        ("item_search_index_s", "item_search"),
                        ("browser_state_s", "browser_state"),
                        ("category_index_s", "category_index"),
                        ("entry_path_index_s", "path_index"),
                        ("entry_basename_index_s", "basename_index"),
                        ("entry_extension_index_s", "extension_index"),
                        ("entry_name_search_index_s", "name_search_index"),
                        ("total_s", "total"),
                    ),
                )
                self.completed.emit(
                    {
                        "entries": entries,
                        "source": source,
                        "cache_path": str(cache_path) if cache_path is not None else "",
                        "browser_state": browser_state,
                        "path_index": path_index,
                        "basename_index": basename_index,
                        "extension_index": extension_index,
                        "name_search_index": name_search_index,
                        "item_search_aliases": item_search_aliases,
                        "item_display_names": item_display_names,
                        "item_exact_display_names": item_exact_display_names,
                        "item_related_display_names": item_related_display_names,
                        "item_asset_catalog": item_asset_catalog,
                        "derived_cache_needs_write": derived_cache_needs_write,
                        "game_executable_fingerprints": self.updated_game_executable_fingerprints,
                        "timings": timings,
                        "timing_summary": timing_summary,
                    }
                )
            except RunCancelled as exc:
                if not self.stop_event.is_set():
                    self.error.emit(str(exc))
            except Exception as exc:
                self.error.emit(str(exc))
            finally:
                if gc_was_enabled:
                    gc.enable()
                self.finished.emit()

    class ArchiveDerivedIndexCacheWriteWorker(QObject):
        log_message = Signal(str)
        finished = Signal()

        def __init__(
            self,
            package_root: Path,
            cache_root: Path,
            entries: Sequence[ArchiveEntry],
            *,
            item_search_aliases: Optional[Mapping[str, str]] = None,
            item_display_names: Optional[Mapping[str, str]] = None,
            item_exact_display_names: Optional[Mapping[str, str]] = None,
            item_related_display_names: Optional[Mapping[str, str]] = None,
            item_asset_catalog: Optional[Sequence[Mapping[str, object]]] = None,
            archive_name_search_index: Optional[ArchiveNameSearchIndex] = None,
        ):
            super().__init__()
            self.package_root = package_root
            self.cache_root = cache_root
            self.entries = entries
            self.item_search_aliases = dict(item_search_aliases or {})
            self.item_display_names = dict(item_display_names or {})
            self.item_exact_display_names = dict(item_exact_display_names or {})
            self.item_related_display_names = dict(item_related_display_names or {})
            self.item_asset_catalog = [dict(row) for row in (item_asset_catalog or []) if isinstance(row, Mapping)]
            self.archive_name_search_index = archive_name_search_index
            self.stop_event = threading.Event()

        def stop(self) -> None:
            self.stop_event.set()

        @Slot()
        def run(self) -> None:
            gc_was_enabled = gc.isenabled()
            if gc_was_enabled:
                gc.disable()
            try:
                if self.stop_event.is_set():
                    return
                self.log_message.emit("Writing lightweight archive derived index cache in background...")
                timings: Dict[str, float] = {}
                save_archive_derived_index_cache(
                    self.package_root,
                    self.cache_root,
                    self.entries,
                    item_search_aliases=self.item_search_aliases,
                    item_display_names=self.item_display_names,
                    item_exact_display_names=self.item_exact_display_names,
                    item_related_display_names=self.item_related_display_names,
                    item_asset_catalog=self.item_asset_catalog,
                    archive_name_search_index=self.archive_name_search_index,
                    on_log=self.log_message.emit,
                    timings=timings,
                )
                elapsed = float(timings.get("derived_cache_write_s", 0.0) or 0.0)
                self.log_message.emit(f"Lightweight archive derived index cache write finished in {elapsed:.2f}s.")
            except Exception as exc:
                self.log_message.emit(f"Warning: archive derived index cache could not be written: {exc}")
            finally:
                if gc_was_enabled:
                    gc.enable()
                self.finished.emit()

    class ArchiveSidecarIndexWorker(QObject):
        log_message = Signal(str)
        progress_changed = Signal(int, int, int, str)
        completed = Signal(int, object)
        error = Signal(int, str)
        finished = Signal(int)

        def __init__(
            self,
            request_id: int,
            package_root: Path,
            cache_root: Path,
            entries: Sequence[ArchiveEntry],
            sidecar_worker_count: int = 0,
        ):
            super().__init__()
            self.request_id = int(request_id)
            self.package_root = package_root
            self.cache_root = cache_root
            self.entries = entries
            self.sidecar_worker_count = max(0, min(16, int(sidecar_worker_count or 0)))
            self.stop_event = threading.Event()

        def stop(self) -> None:
            self.stop_event.set()

        @Slot()
        def run(self) -> None:
            try:
                timings: Dict[str, float] = {}
                started_at = time.perf_counter()
                last_progress_emit_at = 0.0

                def _emit_throttled_progress(current: int, total: int, detail: str) -> None:
                    nonlocal last_progress_emit_at
                    now = time.perf_counter()
                    if total > 0 and current >= total:
                        last_progress_emit_at = now
                        self.progress_changed.emit(self.request_id, current, total, detail)
                        return
                    if now - last_progress_emit_at < 0.75:
                        return
                    last_progress_emit_at = now
                    self.progress_changed.emit(self.request_id, current, total, detail)

                self.log_message.emit("Checking texture sidecar cache metadata...")
                self.progress_changed.emit(
                    self.request_id,
                    0,
                    0,
                    "Checking cache metadata...",
                )
                cached = load_archive_texture_sidecar_cache_rows(
                    self.package_root,
                    self.cache_root,
                    self.entries,
                    worker_count=self.sidecar_worker_count,
                    on_log=self.log_message.emit,
                    stop_event=self.stop_event,
                    timings=timings,
                    on_progress=_emit_throttled_progress,
                )
                if cached is not None:
                    path_rows, basename_rows = cached
                    lazy_index_started_at = time.perf_counter()
                    self.progress_changed.emit(
                        self.request_id,
                        0,
                        0,
                        "Loading cache rows complete. Preparing lazy lookup indexes...",
                    )
                    sidecar_entries_by_texture_path = build_lazy_archive_texture_sidecar_entry_index(
                        path_rows,
                        self.entries,
                    )
                    sidecar_entries_by_texture_basename = build_lazy_archive_texture_sidecar_entry_index(
                        basename_rows,
                        self.entries,
                    )
                    timings["lazy_index_s"] = max(0.0, float(time.perf_counter() - lazy_index_started_at))
                    timings.setdefault("path_row_build_s", 0.0)
                    timings.setdefault("basename_row_build_s", 0.0)
                    timings.setdefault("entry_resolve_s", 0.0)
                    timings.setdefault("cache_write_s", 0.0)
                    timings["total_s"] = max(0.0, float(time.perf_counter() - started_at))
                    timing_summary = _format_timing_summary(
                        "Texture sidecar timings",
                        "cache",
                        timings,
                        (
                            ("cache_check_s", "cache_check"),
                            ("cache_load_s", "cache_load"),
                            ("incremental_remap_s", "remap"),
                            ("incremental_scan_s", "rescan_changed"),
                            ("incremental_update_s", "incremental_update"),
                            ("path_row_build_s", "path_rows"),
                            ("basename_row_build_s", "basename_rows"),
                            ("lazy_index_s", "lazy_index"),
                            ("entry_resolve_s", "resolve"),
                            ("cache_write_s", "cache_write"),
                            ("total_s", "total"),
                        ),
                    )
                    self.completed.emit(
                        self.request_id,
                        {
                            "sidecar_entries_by_texture_path": sidecar_entries_by_texture_path,
                            "sidecar_entries_by_texture_basename": sidecar_entries_by_texture_basename,
                            "sidecar_path_rows": path_rows,
                            "sidecar_basename_rows": basename_rows,
                            "source": "cache",
                            "cache_path": str(resolve_archive_sidecar_cache_path(self.package_root, self.cache_root)),
                            "timings": timings,
                            "timing_summary": timing_summary,
                        },
                    )
                    return

                self.log_message.emit("Indexing texture sidecar bindings for related-file discovery...")
                self.progress_changed.emit(
                    self.request_id,
                    0,
                    0,
                    "Indexing sidecar files...",
                )
                path_rows_started_at = time.perf_counter()
                path_rows = build_archive_texture_sidecar_path_rows(
                    self.entries,
                    worker_count=self.sidecar_worker_count,
                    stop_event=self.stop_event,
                    on_progress=_emit_throttled_progress,
                    timings=timings,
                )
                timings["path_row_build_s"] = max(0.0, float(time.perf_counter() - path_rows_started_at))
                self.progress_changed.emit(
                    self.request_id,
                    0,
                    0,
                    "Building basename lookup...",
                )
                basename_rows_started_at = time.perf_counter()
                basename_rows = build_archive_texture_sidecar_basename_rows(path_rows)
                timings["basename_row_build_s"] = max(0.0, float(time.perf_counter() - basename_rows_started_at))
                lazy_index_started_at = time.perf_counter()
                self.progress_changed.emit(
                    self.request_id,
                    0,
                    0,
                    "Preparing lazy sidecar lookup indexes...",
                )
                sidecar_entries_by_texture_path = build_lazy_archive_texture_sidecar_entry_index(path_rows, self.entries)
                sidecar_entries_by_texture_basename = build_lazy_archive_texture_sidecar_entry_index(
                    basename_rows,
                    self.entries,
                )
                timings["lazy_index_s"] = max(0.0, float(time.perf_counter() - lazy_index_started_at))
                timings["entry_resolve_s"] = 0.0
                if self.stop_event.is_set():
                    return
                cache_path_text = ""
                try:
                    self.progress_changed.emit(
                        self.request_id,
                        0,
                        0,
                        "Writing cache...",
                    )
                    cache_path = save_archive_texture_sidecar_cache(
                        self.package_root,
                        self.cache_root,
                        self.entries,
                        path_rows=path_rows,
                        basename_rows=None,
                        on_log=self.log_message.emit,
                        on_progress=lambda current, total, detail: self.progress_changed.emit(
                            self.request_id,
                            current,
                            total,
                            detail,
                        ),
                        stop_event=self.stop_event,
                        timings=timings,
                    )
                    cache_path_text = str(cache_path)
                except Exception as exc:
                    if not self.stop_event.is_set():
                        self.log_message.emit(f"Warning: texture sidecar cache could not be written: {exc}")
                    timings.setdefault("cache_write_s", 0.0)
                self.progress_changed.emit(self.request_id, 1, 1, "Texture sidecar cache is ready.")
                timings["total_s"] = max(0.0, float(time.perf_counter() - started_at))
                timing_summary = _format_timing_summary(
                    "Texture sidecar timings",
                    "scan",
                    timings,
                    (
                        ("cache_check_s", "cache_check"),
                        ("cache_load_s", "cache_load"),
                        ("path_row_build_s", "path_rows"),
                        ("basename_row_build_s", "basename_rows"),
                        ("lazy_index_s", "lazy_index"),
                        ("entry_resolve_s", "resolve"),
                        ("cache_write_s", "cache_write"),
                        ("total_s", "total"),
                    ),
                )
                if not self.stop_event.is_set():
                    self.completed.emit(
                        self.request_id,
                        {
                            "sidecar_entries_by_texture_path": sidecar_entries_by_texture_path,
                            "sidecar_entries_by_texture_basename": sidecar_entries_by_texture_basename,
                            "sidecar_path_rows": path_rows,
                            "sidecar_basename_rows": basename_rows,
                            "source": "scan",
                            "cache_path": cache_path_text,
                            "timings": timings,
                            "timing_summary": timing_summary,
                        },
                    )
            except RunCancelled as exc:
                if not self.stop_event.is_set():
                    self.error.emit(self.request_id, str(exc))
            except Exception as exc:
                if not self.stop_event.is_set():
                    self.error.emit(self.request_id, str(exc))
            finally:
                self.finished.emit(self.request_id)

    class ArchiveFilterWorker(QObject):
        progress_changed = Signal(int, int, str)
        completed = Signal(object)
        error = Signal(str)
        finished = Signal()

        def __init__(
            self,
            entries: Sequence[ArchiveEntry],
            *,
            entries_by_extension: Optional[Dict[str, Sequence[ArchiveEntry]]] = None,
            entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
            entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
            archive_name_search_index: Optional[ArchiveNameSearchIndex] = None,
            request_signature: Tuple[object, ...] = (),
            preferred_path: str = "",
            build_tree_index: bool = True,
            filter_text: str = "",
            exclude_filter_text: str = "",
            extension_filter: str = "*",
            package_filter_text: str = "",
            structure_filter: str = "",
            role_filter: str = "all",
            exclude_common_technical_suffixes: bool = False,
            min_size_kb: int = 0,
            previewable_only: bool = False,
            build_category_index: bool = True,
            item_search_aliases: Optional[Mapping[str, str]] = None,
            item_display_names: Optional[Mapping[str, str]] = None,
            item_exact_display_names: Optional[Mapping[str, str]] = None,
            item_related_display_names: Optional[Mapping[str, str]] = None,
            sort_column: int = -1,
            sort_order: str = "asc",
        ):
            super().__init__()
            # Keep references instead of copying 1M+ archive entries on the UI thread
            # before the worker even starts running.
            self.entries = entries
            self.entries_by_extension = entries_by_extension or {}
            self.entries_by_normalized_path = entries_by_normalized_path or {}
            self.entries_by_basename = entries_by_basename or {}
            self.archive_name_search_index = archive_name_search_index
            self.request_signature = tuple(request_signature or ())
            self.preferred_path = preferred_path
            self.build_tree_index = build_tree_index
            self.filter_text = filter_text
            self.exclude_filter_text = exclude_filter_text
            self.extension_filter = extension_filter
            self.package_filter_text = package_filter_text
            self.structure_filter = structure_filter
            self.role_filter = role_filter
            self.exclude_common_technical_suffixes = exclude_common_technical_suffixes
            self.min_size_kb = min_size_kb
            self.previewable_only = previewable_only
            self.build_category_index = build_category_index
            self.item_search_aliases = dict(item_search_aliases or {})
            self.item_display_names = dict(item_display_names or {})
            self.item_exact_display_names = dict(item_exact_display_names or {})
            self.item_related_display_names = dict(item_related_display_names or {})
            self.sort_column = normalize_archive_browser_sort_column(sort_column)
            self.sort_order = normalize_archive_browser_sort_order(sort_order)
            self.stop_event = threading.Event()

        def stop(self) -> None:
            self.stop_event.set()

        @Slot()
        def run(self) -> None:
            try:
                source_entries = self.entries
                normalized_extension = normalize_archive_extension_filter(self.extension_filter)
                if normalized_extension and normalized_extension not in {"*", "all", ".*"} and self.entries_by_extension:
                    source_entries = self.entries_by_extension.get(normalized_extension, [])
                browser_state = prepare_archive_browser_state(
                    source_entries,
                    filter_text=self.filter_text,
                    exclude_filter_text=self.exclude_filter_text,
                    extension_filter=self.extension_filter,
                    package_filter_text=self.package_filter_text,
                    structure_filter=self.structure_filter,
                    role_filter=self.role_filter,
                    exclude_common_technical_suffixes=self.exclude_common_technical_suffixes,
                    min_size_kb=self.min_size_kb,
                    previewable_only=self.previewable_only,
                    item_search_aliases=self.item_search_aliases,
                    archive_entries_by_basename=self.entries_by_basename,
                    archive_entries_by_normalized_path=self.entries_by_normalized_path,
                    archive_name_search_index=self.archive_name_search_index,
                    build_structure_children=False,
                    build_tree_index=self.build_tree_index,
                    sort_column=self.sort_column,
                    sort_order=self.sort_order,
                    item_display_names=self.item_display_names,
                    item_exact_display_names=self.item_exact_display_names,
                    item_related_display_names=self.item_related_display_names,
                    on_progress=self.progress_changed.emit,
                    stop_event=self.stop_event,
                )
                if self.build_category_index:
                    browser_state["category_entry_indexes"] = build_archive_category_entry_index(
                        browser_state.get("filtered_entries", ()),
                        on_progress=self.progress_changed.emit,
                        stop_event=self.stop_event,
                    )
                else:
                    browser_state["category_entry_indexes"] = {}
                self.completed.emit(
                    {
                        "browser_state": browser_state,
                        "request_signature": self.request_signature,
                        "preferred_path": self.preferred_path,
                    }
                )
            except RunCancelled:
                pass
            except Exception as exc:
                self.error.emit(str(exc))
            finally:
                self.finished.emit()

    class BuildWorker(QObject):
        log_message = Signal(str)
        phase_changed = Signal(str, str, bool)
        phase_progress_changed = Signal(int, int, str)
        total_found = Signal(int)
        current_file = Signal(str)
        progress = Signal(int, int, int, int, int)
        completed = Signal(object)
        cancelled = Signal(str)
        error = Signal(str)
        finished = Signal()

        def __init__(self, config: AppConfig):
            super().__init__()
            self.config = config
            self.stop_event = threading.Event()

        def stop(self) -> None:
            self.stop_event.set()

        @Slot()
        def run(self) -> None:
            breadcrumb_state = _texture_workflow_breadcrumb_base(self.config, "BuildWorker")

            def write_breadcrumb(**updates: object) -> None:
                breadcrumb_state.update(updates)
                breadcrumb_state["timestamp"] = time.time()
                _write_texture_workflow_breadcrumb(breadcrumb_state)

            def emit_log(message: str) -> None:
                self.log_message.emit(message)
                if _is_texture_workflow_tool_log(message):
                    write_breadcrumb(last_external_tool_step=str(message))

            def emit_total(total: int) -> None:
                write_breadcrumb(total_files=total)
                self.total_found.emit(total)

            def emit_current_file(current_file: str) -> None:
                write_breadcrumb(current_file=current_file)
                self.current_file.emit(current_file)

            def emit_progress(processed: int, total: int, converted: int, skipped: int, failed: int) -> None:
                write_breadcrumb(
                    processed=processed,
                    total_files=total,
                    converted=converted,
                    skipped=skipped,
                    failed=failed,
                )
                self.progress.emit(processed, total, converted, skipped, failed)

            def emit_phase(phase_name: str, detail: str, indeterminate: bool) -> None:
                write_breadcrumb(phase=phase_name, phase_detail=detail, phase_indeterminate=indeterminate)
                self.phase_changed.emit(phase_name, detail, indeterminate)

            def emit_phase_progress(current: int, total: int, detail: str) -> None:
                write_breadcrumb(phase_current=current, phase_total=total, phase_progress_detail=detail)
                self.phase_progress_changed.emit(current, total, detail)

            write_breadcrumb(phase="starting", phase_detail="Texture workflow build starting")
            try:
                summary = rebuild_dds_files(
                    self.config,
                    on_log=emit_log,
                    on_total=emit_total,
                    on_current_file=emit_current_file,
                    on_progress=emit_progress,
                    on_phase=emit_phase,
                    on_phase_progress=emit_phase_progress,
                    stop_event=self.stop_event,
                )
                if summary.cancelled:
                    write_breadcrumb(status="cancelled", phase_detail="Processing stopped by user.")
                    self.cancelled.emit("Processing stopped by user.")
                else:
                    write_breadcrumb(
                        status="completed",
                        total_files=summary.total_files,
                        converted=summary.converted,
                        skipped=summary.skipped,
                        failed=summary.failed,
                    )
                    self.completed.emit(summary)
            except Exception as exc:
                write_breadcrumb(status="error", error=str(exc))
                self.error.emit(str(exc))
            finally:
                if breadcrumb_state.get("status") == "running":
                    write_breadcrumb(status="finished")
                else:
                    write_breadcrumb()
                self.finished.emit()

