        def autodetect_archive_package_root(self) -> None:
            if self._background_task_active():
                return

            def task(on_log: Callable[[str], None]) -> List[str]:
                on_log("Auto-detecting Crimson Desert archive package roots from known install locations...")
                roots = autodetect_archive_package_roots(on_log=on_log)
                return [str(path) for path in roots]

            def on_complete(result: object) -> None:
                candidates = [str(item) for item in result] if isinstance(result, list) else []
                if not candidates:
                    self.set_status_message(
                        "No valid Crimson Desert archive package root was auto-detected. Use Browse to set it manually.",
                        error=True,
                    )
                    return

                selected_path = candidates[0]
                if len(candidates) > 1:
                    selected_path, accepted = QInputDialog.getItem(
                        self,
                        "Select Package Root",
                        "Multiple Crimson Desert package roots were found. Choose one:",
                        candidates,
                        0,
                        False,
                    )
                    if not accepted or not selected_path:
                        self.set_status_message("Archive package root auto-detect cancelled.")
                        return

                self.archive_package_root_edit.setText(selected_path)
                self._activate_tool_widget(self.archive_browser_tab)
                self.set_status_message(f"Auto-detected archive package root: {selected_path}")
                self.append_log(f"Using detected archive package root: {selected_path}")

            self._run_utility_task(
                status_message="Auto-detecting archive package root...",
                task=task,
                on_complete=on_complete,
            )

        def _suggest_workspace_base_dir(self) -> str:
            common = common_workspace_root_from_config(self.collect_config())
            if common is not None:
                return str(common)
            return str(Path.cwd())

        def _run_utility_task(
            self,
            *,
            status_message: str,
            task: Callable[..., object],
            on_complete: Optional[Callable[[object], None]] = None,
            show_archive_progress: bool = False,
            task_accepts_progress: bool = False,
            task_accepts_cancel: bool = False,
        ) -> None:
            if self._background_task_active():
                if self.worker_thread is not None:
                    self.set_status_message(
                        "Another background task is still running. Wait for it to finish before starting this action.",
                        error=True,
                    )
                return

            self.set_status_message(status_message)
            self.append_log(status_message)
            self._utility_updates_archive_progress = bool(show_archive_progress)
            if self._utility_updates_archive_progress:
                self.archive_scan_progress_label.setText(status_message)
                self.archive_scan_progress_bar.setRange(0, 0)
                self.archive_scan_progress_bar.setFormat("Working...")
                self.append_archive_log(status_message)

            worker = UtilityWorker(
                task,
                task_accepts_progress=task_accepts_progress,
                task_accepts_cancel=task_accepts_cancel,
            )
            thread = QThread(self)
            worker.moveToThread(thread)

            thread.started.connect(worker.run)
            worker.log_message.connect(self._handle_utility_log_message)
            worker.progress_changed.connect(self._handle_utility_progress_changed)
            worker.completed.connect(self._handle_utility_completed)
            worker.error.connect(self._handle_worker_error)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            thread.finished.connect(self._cleanup_worker_refs)

            self.utility_worker = worker
            self.worker_thread = thread
            self._utility_completion_handler = on_complete
            self.set_busy(True, build_mode=task_accepts_cancel)
            thread.start()

        def _run_utility_task_when_idle(
            self,
            *,
            status_message: str,
            task: Callable[..., object],
            on_complete: Optional[Callable[[object], None]] = None,
            show_archive_progress: bool = False,
            task_accepts_progress: bool = False,
            task_accepts_cancel: bool = False,
            attempt: int = 0,
        ) -> None:
            if self.worker_thread is None:
                self._run_utility_task(
                    status_message=status_message,
                    task=task,
                    on_complete=on_complete,
                    show_archive_progress=show_archive_progress,
                    task_accepts_progress=task_accepts_progress,
                    task_accepts_cancel=task_accepts_cancel,
                )
                return
            if attempt == 0:
                self.append_log("Waiting for the current background task to finish before starting the next step.")
                if show_archive_progress:
                    self.append_archive_log("Waiting for the current background task to finish before starting the next step.")
            if attempt >= 100:
                message = "Could not start the next background step because the previous task did not finish cleanly."
                self.set_status_message(message, error=True)
                self.append_log(f"ERROR: {message}")
                if show_archive_progress:
                    self.append_archive_log(f"ERROR: {message}")
                return
            QTimer.singleShot(
                50,
                lambda: self._run_utility_task_when_idle(
                    status_message=status_message,
                    task=task,
                    on_complete=on_complete,
                    show_archive_progress=show_archive_progress,
                    task_accepts_progress=task_accepts_progress,
                    task_accepts_cancel=task_accepts_cancel,
                    attempt=attempt + 1,
                ),
            )

        def _handle_utility_log_message(self, message: str) -> None:
            self.append_log(message)
            if not self._utility_updates_archive_progress:
                return
            if message.startswith("[") and ("] EXTRACT " in message or "] FAIL " in message):
                return
            self.archive_scan_progress_label.setText(message)
            self.archive_scan_progress_bar.setRange(0, 0)
            self.archive_scan_progress_bar.setFormat("Working...")
            self.append_archive_log(message)
            self.set_status_message(message)

        def _handle_utility_progress_changed(self, current: int, total: int, detail: str) -> None:
            if not self._utility_updates_archive_progress:
                return
            detail_text = str(detail or "").strip() or "Working..."
            self.archive_scan_progress_label.setText(detail_text)
            if total > 0:
                bounded_current = min(max(int(current), 0), int(total))
                self.archive_scan_progress_bar.setRange(0, int(total))
                self.archive_scan_progress_bar.setValue(bounded_current)
                self.archive_scan_progress_bar.setFormat("Archive files: %v / %m")
            else:
                self.archive_scan_progress_bar.setRange(0, 0)
                self.archive_scan_progress_bar.setFormat(detail_text)
            self.set_status_message(detail_text)

        def _directory_has_contents(self, path: Path) -> bool:
            try:
                if not path.exists() or not path.is_dir():
                    return False
                next(path.iterdir())
                return True
            except StopIteration:
                return False
            except OSError:
                return False

        def _prompt_clear_directory_before_start(self, label: str, path: Path) -> Optional[bool]:
            if not self._directory_has_contents(path):
                return False

            box = QMessageBox(self)
            box.setWindowTitle(f"{label} Not Empty")
            box.setIcon(QMessageBox.Warning)
            box.setText(f"{label} already contains files or folders.")
            box.setInformativeText(
                f"{path}\n\n"
                "Clear it before starting?\n"
                "Choose Keep Existing to leave the current contents in place, or Cancel to stop."
            )
            clear_button = box.addButton("Clear Folder", QMessageBox.DestructiveRole)
            keep_button = box.addButton("Keep Existing", QMessageBox.AcceptRole)
            cancel_button = box.addButton(QMessageBox.Cancel)
            box.setDefaultButton(keep_button)
            box.exec()

            clicked = box.clickedButton()
            if clicked == cancel_button:
                return None
            return clicked == clear_button

        def _prepare_workflow_output_roots_for_start(
            self,
            config: AppConfig,
            *,
            include_output_root: bool,
        ) -> bool:
            if config.dry_run:
                return True

            targets = self._workflow_start_cleanup_targets(
                config,
                include_output_root=include_output_root,
            )

            seen_paths: set[str] = set()
            unique_targets: List[Tuple[str, str, Path]] = []
            for key, label, path in targets:
                try:
                    normalized_key = str(path.resolve())
                except OSError:
                    normalized_key = str(path)
                if normalized_key in seen_paths:
                    continue
                seen_paths.add(normalized_key)
                unique_targets.append((key, label, path))

            cleared_target_keys: set[str] = set()
            for key, label, path in unique_targets:
                if not self._preference_bool("confirm_workflow_output_cleanup", True):
                    self.append_log(f"Keeping existing contents in {label}: {path} (cleanup confirmation disabled)")
                    continue
                decision = self._prompt_clear_directory_before_start(label, path)
                if decision is None:
                    self.set_status_message("Start cancelled.")
                    self.append_log(f"Start cancelled while reviewing {label.lower()} contents.")
                    return False
                if not decision:
                    self.append_log(f"Keeping existing contents in {label}: {path}")
                    continue
                path.mkdir(parents=True, exist_ok=True)
                clear_directory_contents(path)
                self.append_log(f"Cleared {label} before start: {path}")
                cleared_target_keys.add(key)

            if "input_dds" in cleared_target_keys:
                self._apply_pending_archive_workflow_extract_if_needed(force=True)
            if "texture_editor_png_root" in cleared_target_keys:
                self._apply_pending_texture_editor_workflow_export_if_needed(force=True)

            return True

        def clear_workflow_roots(self) -> None:
            targets = self._manual_workflow_cleanup_targets()
            lines: List[str] = []
            configured_targets: List[Tuple[str, Path]] = []
            seen_paths: set[str] = set()
            for key, label, path in targets:
                if path is None:
                    lines.append(f"- {label}: not configured")
                    continue
                try:
                    resolved_path = path.resolve()
                except OSError:
                    resolved_path = path
                lines.append(f"- {label}: {resolved_path}")
                normalized_key = str(resolved_path)
                if normalized_key in seen_paths:
                    continue
                seen_paths.add(normalized_key)
                configured_targets.append((label, resolved_path))

            box = QMessageBox(self)
            box.setWindowTitle("Clear Workflow Roots")
            box.setIcon(QMessageBox.Warning)
            box.setText("This will clear the configured workflow staging/output folders listed below.")
            box.setInformativeText("\n".join(lines))
            clear_button = box.addButton("Clear Folders", QMessageBox.AcceptRole)
            cancel_button = box.addButton(QMessageBox.Cancel)
            box.setDefaultButton(cancel_button)
            box.exec()
            if box.clickedButton() != clear_button:
                self.set_status_message("Workflow root cleanup cancelled.")
                return

            cleared_count = 0
            for label, resolved_path in configured_targets:
                resolved_path.mkdir(parents=True, exist_ok=True)
                clear_directory_contents(resolved_path)
                self.append_log(f"Cleared {label}: {resolved_path}")
                cleared_count += 1

            self.set_status_message(f"Cleared {cleared_count} configured workflow folder(s).")

        def initialize_workspace(self) -> None:
            selected = QFileDialog.getExistingDirectory(
                self,
                "Select Workspace Folder",
                self._suggest_workspace_base_dir(),
            )
            if not selected:
                return

            base_dir = Path(selected)

            def task(on_log: Callable[[str], None]) -> Dict[str, str]:
                on_log(f"Creating workspace structure under {base_dir}")
                paths = create_workspace_structure(base_dir)
                return {key: str(value) for key, value in paths.items()}

            def on_complete(result: object) -> None:
                if not isinstance(result, dict):
                    return
                self.original_dds_edit.setText(str(result["original_dds_root"]))
                self.png_root_edit.setText(str(result["png_root"]))
                if not self.texture_editor_png_root_edit.text().strip():
                    self.texture_editor_png_root_edit.setText(str(result["texture_editor_png_root"]))
                if not self.dds_staging_root_edit.text().strip():
                    self.dds_staging_root_edit.setText(str(result["dds_staging_root"]))
                self.output_root_edit.setText(str(result["output_root"]))
                if not self.archive_extract_root_edit.text().strip():
                    self.archive_extract_root_edit.setText(str(result["archive_extract_root"]))
                if not self.texconv_path_edit.text().strip():
                    self.texconv_path_edit.setText(str(result["texconv_path"]))
                if not self.csv_log_path_edit.text().strip():
                    self.csv_log_path_edit.setText(str(result["csv_log_path"]))
                if not self.chainner_exe_path_edit.text().strip():
                    self.chainner_exe_path_edit.setText(str(result["chainner_exe_path"]))
                if not self.ncnn_exe_path_edit.text().strip():
                    self.ncnn_exe_path_edit.setText(str(result["ncnn_exe_path"]))
                if not self.ncnn_model_dir_edit.text().strip():
                    self.ncnn_model_dir_edit.setText(str(result["ncnn_model_dir"]))
                if not self.mod_ready_export_root_edit.text().strip():
                    self.mod_ready_export_root_edit.setText(str(result["mod_ready_export_root"]))
                self._refresh_ncnn_model_picker()
                self.set_status_message(f"Workspace initialized at {base_dir}")
                self.append_log("Workspace initialization complete.")

            self._run_utility_task(
                status_message="Initializing workspace...",
                task=task,
                on_complete=on_complete,
            )

        def create_missing_folders(self) -> None:
            config = self.collect_config()

            def task(on_log: Callable[[str], None]) -> List[str]:
                created = create_missing_directories_for_config(config)
                if created:
                    for path in created:
                        on_log(f"Created folder: {path}")
                else:
                    on_log("No folders needed to be created.")
                return [str(path) for path in created]

            def on_complete(result: object) -> None:
                created = result if isinstance(result, list) else []
                if created:
                    self.set_status_message(f"Created {len(created)} folder(s).")
                else:
                    self.set_status_message("All requested folders already existed.")

            self._run_utility_task(
                status_message="Creating missing folders...",
                task=task,
                on_complete=on_complete,
            )

        def open_chainner_download_page(self) -> None:
            self._open_external_urls([CHAINNER_DOWNLOAD_PAGE_URL], label="chaiNNer")

        def open_texconv_download_page(self) -> None:
            self._open_external_urls([DIRECTXTEX_RELEASES_PAGE_URL], label="texconv")

        def open_realesrgan_ncnn_download_page(self) -> None:
            self._open_external_urls([REALESRGAN_NCNN_RELEASES_PAGE_URL], label="Real-ESRGAN NCNN")

        def _confirm_model_import_expectations(self, model_kind: str) -> bool:
            box = QMessageBox(self)
            box.setIcon(QMessageBox.Information)
            box.setWindowTitle("Import NCNN Models")
            box.setText("Expected NCNN model contents")
            box.setInformativeText(
                "Choose a folder, zip, or file set that contains at least one matching "
                ".param + .bin pair with the same base name."
            )
            box.setDetailedText(
                "Example:\n"
                "  realesr-animevideov3.param\n"
                "  realesr-animevideov3.bin\n\n"
                "Nested folders inside a zip are fine.\n"
                "Unsupported examples include a single .param without its .bin partner,\n"
                "random checkpoint formats, or the NCNN executable folder without model files."
            )
            continue_button = box.addButton("Continue", QMessageBox.AcceptRole)
            box.addButton(QMessageBox.Cancel)
            box.exec()
            return box.clickedButton() is continue_button

        def _choose_model_import_sources(self, title: str, *, model_kind: str) -> List[Path]:
            if not self._confirm_model_import_expectations(model_kind):
                return []
            mode, accepted = QInputDialog.getItem(
                self,
                title,
                "Import from:",
                ["Folder", "Files or zip"],
                0,
                False,
            )
            if not accepted or not mode:
                return []
            if mode == "Folder":
                selected = QFileDialog.getExistingDirectory(self, title, self._suggest_workspace_base_dir())
                return [Path(selected)] if selected else []
            selected_files, _ = QFileDialog.getOpenFileNames(
                self,
                title,
                self._suggest_workspace_base_dir(),
                "NCNN model files (*.param *.bin *.zip);;All files (*.*)",
            )
            return [Path(path) for path in selected_files]

        def _choose_model_destination(self, title: str, current_text: str) -> Optional[Path]:
            start_dir = self._pick_existing_directory(current_text) if current_text else self._suggest_workspace_base_dir()
            selected = QFileDialog.getExistingDirectory(self, title, start_dir)
            if not selected:
                return None
            return Path(selected)

        def import_ncnn_models(self) -> None:
            sources = self._choose_model_import_sources("Import NCNN Models", model_kind="ncnn")
            if not sources:
                return
            destination = self._choose_model_destination(
                "Select NCNN Model Folder",
                self.ncnn_model_dir_edit.text().strip(),
            )
            if destination is None:
                return

            def task(on_log: Callable[[str], None]) -> List[str]:
                pairs = validate_ncnn_model_import_sources(sources)
                on_log(f"Detected {len(pairs)} valid NCNN model pair(s): {', '.join(pairs[:5])}")
                imported = import_model_assets_to_directory(
                    sources,
                    destination,
                    allowed_suffixes=(".param", ".bin"),
                    on_log=on_log,
                )
                return [str(path) for path in imported]

            def on_complete(result: object) -> None:
                imported = result if isinstance(result, list) else []
                self.ncnn_model_dir_edit.setText(str(destination))
                self._refresh_ncnn_model_picker()
                self.set_status_message(f"Imported {len(imported)} NCNN model file(s).")

            self._run_utility_task(
                status_message="Importing NCNN models...",
                task=task,
                on_complete=on_complete,
            )

        def _suggest_archive_extract_root(self) -> Path:
            text = self.archive_extract_root_edit.text().strip()
            if text:
                return Path(text).expanduser()
            common = common_workspace_root_from_config(self.collect_config())
            if common is not None:
                return suggested_workspace_paths(common).get("archive_extract_root", common / "archive_extract")
            return Path.cwd() / "archive_extract"

        def _stop_archive_sidecar_worker(self) -> None:
            if self.archive_sidecar_worker is not None:
                try:
                    self.archive_sidecar_worker.stop()
                except Exception:
                    pass

        def _stop_archive_derived_cache_worker(self) -> None:
            self.archive_derived_cache_write_pending = False
            if self.archive_derived_cache_worker is not None:
                try:
                    self.archive_derived_cache_worker.stop()
                except Exception:
                    pass

        def scan_archives(self, force_refresh: bool = False, *, activate_archive_tab: bool = True) -> None:
            self._cancel_archive_tree_population()
            self._archive_scan_progress_timer.stop()
            self._archive_scan_progress_pending = None
            if self._background_task_active():
                return
            self._stop_archive_sidecar_worker()
            self._stop_archive_derived_cache_worker()
            self.archive_sidecar_request_id += 1
            self.archive_sidecar_pending_start = False
            package_root_text = self.archive_package_root_edit.text().strip()
            if not package_root_text:
                self.set_status_message("Set an archive package root first.", error=True)
                return

            package_root = Path(package_root_text).expanduser()
            self._activate_archive_browser_on_scan_complete = activate_archive_tab
            if activate_archive_tab:
                self._activate_tool_widget(self.archive_browser_tab)
            self.archive_scan_progress_label.setText("Preparing archive refresh..." if force_refresh else "Preparing archive scan / cache load...")
            self.archive_scan_progress_bar.setRange(0, 0)
            self.archive_scan_progress_bar.setFormat("Working...")
            self._update_startup_splash("Preparing archive refresh..." if force_refresh else "Preparing archive scan / cache load...")
            _write_heartbeat("archive_refresh" if force_refresh else "archive_load")
            self._set_archive_warmup_overlay(
                True,
                "Preparing Archive Browser",
                (
                    "Loading the archive index first. Texture sidecar bindings can continue warming in the background "
                    "after the browser opens."
                ),
            )
            self.set_status_message("Refreshing archives..." if force_refresh else "Loading archives...")
            self.append_log("Refreshing archives..." if force_refresh else "Loading archives...")
            self.clear_archive_scan_log()
            self.append_archive_log(
                "Starting archive refresh." if force_refresh else "Starting archive scan (cache-aware)."
            )
            _set_last_active_operation(
                "archive_scan",
                package_root=str(package_root),
                force_refresh=force_refresh,
            )

            browser_view_will_render_now = bool(
                activate_archive_tab or self._is_tool_visible_or_current(self.archive_browser_tab)
            )
            startup_deferred_archive_load = bool(
                getattr(self, "archive_startup_autoload_defer_preview", False)
                and not activate_archive_tab
                and getattr(self, "_startup_splash_window", None) is not None
            )
            build_browser_tree_index = bool(
                self._archive_folder_tree_enabled()
                and browser_view_will_render_now
                and not startup_deferred_archive_load
            )
            build_browser_category_index = bool(
                self._archive_category_view_enabled()
                and browser_view_will_render_now
                and not startup_deferred_archive_load
            )
            worker = ArchiveScanWorker(
                package_root,
                self.archive_cache_root,
                force_refresh=force_refresh,
                build_tree_index=build_browser_tree_index,
                filter_text=self.archive_filter_edit.text().strip(),
                exclude_filter_text=self.archive_exclude_filter_edit.text().strip(),
                extension_filter=self._combo_value(self.archive_extension_filter_combo),
                package_filter_text=self.archive_package_filter_edit.text().strip(),
                structure_filter=self._current_archive_structure_filter_value(),
                role_filter=self._combo_value(self.archive_role_filter_combo),
                exclude_common_technical_suffixes=self.archive_exclude_common_technical_checkbox.isChecked(),
                min_size_kb=self.archive_min_size_spin.value(),
                previewable_only=self.archive_previewable_only_checkbox.isChecked(),
                build_category_index=build_browser_category_index,
                sort_column=self.archive_tree_sort_column,
                sort_order=self.archive_tree_sort_order,
                game_executable_fingerprints=self._load_game_executable_fingerprints(),
                crash_reports_dir=crash_reports_dir,
            )
            thread = QThread(self)
            worker.moveToThread(thread)

            thread.started.connect(worker.run)
            worker.log_message.connect(self.append_log)
            worker.log_message.connect(self.append_archive_log)
            worker.progress_changed.connect(self._handle_archive_scan_progress)
            worker.completed.connect(self._handle_archive_scan_complete)
            worker.error.connect(self._handle_worker_error)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            thread.finished.connect(self._cleanup_worker_refs)

            self.archive_scan_worker = worker
            self.worker_thread = thread
            self.set_busy(True, build_mode=False)
            thread.start()

        def _set_archive_warmup_overlay(
            self,
            visible: bool,
            title: str = "",
            message: str = "",
            *,
            current: int = 0,
            total: int = 0,
            fmt: str = "",
        ) -> None:
            if not hasattr(self, "archive_warmup_overlay"):
                return
            self.archive_warmup_overlay.hide()

        def _apply_archive_scan_progress(self, current: int, total: int, detail: str) -> None:
            self.archive_scan_progress_label.setText(detail)
            self._update_startup_splash(detail, current, total)
            if total > 0:
                completed_value = min(max(current, 0), total)
                display_value = min(completed_value + 1, total) if detail.startswith("Parsing ") else completed_value
                self.archive_scan_progress_bar.setRange(0, total)
                self.archive_scan_progress_bar.setValue(completed_value)
                self.archive_scan_progress_bar.setFormat(f"{display_value} / {total}")
                self._set_archive_warmup_overlay(
                    True,
                    "Scanning Archive Packages",
                    detail,
                    current=completed_value,
                    total=total,
                    fmt=f"{display_value} / {total}",
                )
            else:
                self.archive_scan_progress_bar.setRange(0, 0)
                self.archive_scan_progress_bar.setFormat("Working...")
                self._set_archive_warmup_overlay(
                    True,
                    "Scanning Archive Packages",
                    detail,
                )
            self.set_status_message(detail)

        def _flush_archive_scan_progress(self) -> None:
            pending = self._archive_scan_progress_pending
            if pending is None:
                return
            self._archive_scan_progress_pending = None
            self._archive_scan_progress_last_flush = time.perf_counter()
            current, total, detail = pending
            self._apply_archive_scan_progress(current, total, detail)

        def _handle_archive_scan_progress(self, current: int, total: int, detail: str) -> None:
            self._archive_scan_progress_pending = (int(current or 0), int(total or 0), str(detail or "Working..."))
            now = time.perf_counter()
            elapsed = now - self._archive_scan_progress_last_flush
            if elapsed >= self._archive_scan_progress_min_interval_s:
                self._archive_scan_progress_timer.stop()
                self._flush_archive_scan_progress()
                return
            if not self._archive_scan_progress_timer.isActive():
                delay_ms = max(1, int((self._archive_scan_progress_min_interval_s - elapsed) * 1000.0))
                self._archive_scan_progress_timer.start(delay_ms)

        def _handle_archive_scan_complete(self, result: object) -> None:
            self._flush_archive_scan_progress()
            payload = result if isinstance(result, dict) else {}
            updated_fingerprints = payload.get("game_executable_fingerprints")
            if isinstance(updated_fingerprints, Mapping):
                self._save_game_executable_fingerprints(updated_fingerprints)
            self._clear_archive_preview_cache()
            self.archive_entries = payload.get("entries", []) if isinstance(payload.get("entries"), list) else []
            self.archive_entries_by_normalized_path = (
                payload.get("path_index", {})
                if isinstance(payload.get("path_index"), dict)
                else {}
            )
            if not self.archive_entries_by_normalized_path and self.archive_entries:
                self.archive_entries_by_normalized_path = build_archive_entry_path_index(self.archive_entries)
            self.archive_entries_by_basename = (
                payload.get("basename_index", {})
                if isinstance(payload.get("basename_index"), dict)
                else {}
            )
            self.archive_entries_by_extension = (
                payload.get("extension_index", {})
                if isinstance(payload.get("extension_index"), dict)
                else {}
            )
            name_search_index = payload.get("name_search_index")
            self.archive_name_search_index = (
                name_search_index
                if isinstance(name_search_index, ArchiveNameSearchIndex)
                else None
            )
            self.archive_item_search_aliases = (
                payload.get("item_search_aliases", {})
                if isinstance(payload.get("item_search_aliases"), dict)
                else {}
            )
            self.archive_item_display_names = (
                payload.get("item_display_names", {})
                if isinstance(payload.get("item_display_names"), dict)
                else {}
            )
            self.archive_item_exact_display_names = (
                payload.get("item_exact_display_names", {})
                if isinstance(payload.get("item_exact_display_names"), dict)
                else {}
            )
            self.archive_item_related_display_names = (
                payload.get("item_related_display_names", {})
                if isinstance(payload.get("item_related_display_names"), dict)
                else {}
            )
            self.archive_item_asset_catalog = [
                dict(row)
                for row in (payload.get("item_asset_catalog", []) or [])
                if isinstance(row, Mapping)
            ]
            self._clear_archive_asset_catalog_icon_cache()
            self._schedule_archive_asset_catalog_icon_preload()
            self.archive_active_asset_catalog_scope = ""
            self.archive_clear_asset_scope_button.setVisible(False)
            self.archive_clear_asset_scope_button.setEnabled(False)
            self.archive_filter_edit.setPlaceholderText("Include path/item-name filter or glob, e.g. Vow of the Dead King or */texture/*")
            self.archive_asset_catalog_button.setEnabled(bool(self.archive_item_asset_catalog))
            self.archive_derived_cache_write_pending = bool(
                payload.get("derived_cache_needs_write") and self.archive_entries
            )
            self.archive_sidecar_entries_by_texture_path = (
                payload.get("sidecar_entries_by_texture_path", {})
                if isinstance(payload.get("sidecar_entries_by_texture_path"), Mapping)
                else {}
            )
            self.archive_sidecar_entries_by_texture_basename = (
                payload.get("sidecar_entries_by_texture_basename", {})
                if isinstance(payload.get("sidecar_entries_by_texture_basename"), Mapping)
                else {}
            )
            self.archive_sidecar_generation += 1
            performance_settings = self._current_archive_performance_settings()
            self.archive_sidecar_pending_start = bool(
                self.archive_entries and performance_settings.enable_sidecar_indexing
            )
            if not performance_settings.enable_sidecar_indexing:
                self.archive_sidecar_entries_by_texture_path = {}
                self.archive_sidecar_entries_by_texture_basename = {}
            if not self.archive_entries_by_extension and self.archive_entries:
                self.archive_entries_by_extension = build_archive_entry_extension_index(self.archive_entries)
            package_root_text = self.archive_package_root_edit.text().strip()
            QTimer.singleShot(
                0,
                lambda entries=self.archive_entries, package_root_text=package_root_text: self.text_search_tab.set_archive_entries(
                    entries,
                    package_root_text,
                ),
            )
            browser_state = payload.get("browser_state") if isinstance(payload.get("browser_state"), dict) else {}
            self.archive_structure_filter_children = (
                browser_state.get("structure_children", {})
                if isinstance(browser_state.get("structure_children"), dict)
                else {}
            )
            self.archive_filtered_entries = (
                browser_state.get("filtered_entries", [])
                if isinstance(browser_state.get("filtered_entries"), list)
                else []
            )
            self.archive_tree_child_folders = (
                browser_state.get("tree_child_folders", {})
                if isinstance(browser_state.get("tree_child_folders"), dict)
                else {}
            )
            self.archive_tree_direct_files = (
                browser_state.get("tree_direct_files", {})
                if isinstance(browser_state.get("tree_direct_files"), dict)
                else {}
            )
            self.archive_tree_folder_entry_indexes = (
                browser_state.get("tree_folder_entry_indexes", {})
                if isinstance(browser_state.get("tree_folder_entry_indexes"), dict)
                else {}
            )
            self.archive_tree_folder_preview_stats = (
                browser_state.get("tree_folder_preview_stats", {})
                if isinstance(browser_state.get("tree_folder_preview_stats"), dict)
                else {}
            )
            self.archive_tree_category_entry_indexes = (
                browser_state.get("category_entry_indexes", {})
                if isinstance(browser_state.get("category_entry_indexes"), dict)
                else {}
            )
            self.archive_tree_index_ready = bool(browser_state.get("tree_index_ready", True))
            self._rebuild_archive_extension_filter_choices()
            self.archive_tree_items_by_folder_key = {}
            self.archive_filtered_dds_count = int(browser_state.get("dds_count", 0))
            self.archive_filters_dirty = False
            self._update_archive_filter_button_state()
            QTimer.singleShot(
                0,
                lambda entries=self.archive_entries, package_root_text=package_root_text: self.replace_assistant_tab.set_archive_entries(
                    entries,
                    package_root_text,
                ),
            )
            source = str(payload.get("source", "scan"))
            cache_path_text = str(payload.get("cache_path", "")).strip()
            timings = payload.get("timings", {}) if isinstance(payload.get("timings"), dict) else {}
            timing_summary = str(payload.get("timing_summary", "")).strip()
            rendering_archive_view = (
                self._activate_archive_browser_on_scan_complete
                or self._is_tool_visible_or_current(self.archive_browser_tab)
            )
            _write_heartbeat("archive_finalize")
            self.archive_scan_progress_label.setText(
                "Rendering archive browser view..." if rendering_archive_view else "Finalizing archive load..."
            )
            self.archive_scan_progress_bar.setRange(0, 0)
            self.archive_scan_progress_bar.setFormat("Rendering..." if rendering_archive_view else "Finalizing...")
            self.set_status_message("Rendering archive browser view..." if rendering_archive_view else "Finalizing archive load...")
            self.append_archive_log("Rendering archive browser view..." if rendering_archive_view else "Finalizing archive load...")
            self.archive_scan_finalize_pending = True
            QTimer.singleShot(
                0,
                lambda source=source, cache_path_text=cache_path_text, timings=timings, timing_summary=timing_summary: self._finalize_archive_scan_complete(
                    source,
                    cache_path_text,
                    timings,
                    timing_summary,
                ),
            )

        def _finalize_archive_scan_complete(
            self,
            source: str,
            cache_path_text: str,
            timings: Optional[Dict[str, float]] = None,
            timing_summary: str = "",
        ) -> None:
            start_sidecar_after_finalize = False
            try:
                completion_text = (
                    f"Loaded {len(self.archive_entries):,} archive entries from cache."
                    if source == "cache"
                    else f"Archive scan complete. Found {len(self.archive_entries):,} entries."
                )
                _record_runtime_event(
                    "archive_scan_complete",
                    source=source,
                    entry_count=len(self.archive_entries),
                    cache_path=cache_path_text,
                    timing_summary=timing_summary,
                )
                if cache_path_text and source == "scan":
                    self.append_archive_log(f"Archive cache ready: {cache_path_text}")
                if timing_summary:
                    self.append_archive_log(timing_summary, verbose=True)
                if source == "cache" and _timing_value(timings, "total_s") > 2.0:
                    self.append_archive_log(
                        f"WARNING: Archive cache hit is slower than expected: total={_timing_value(timings, 'total_s'):.2f}s.",
                        verbose=True,
                    )
                performance_settings = self._current_archive_performance_settings()
                if (
                    self.archive_sidecar_pending_start
                    and self.archive_entries
                    and performance_settings.enable_sidecar_indexing
                ):
                    start_sidecar_after_finalize = True
                    self.archive_browser_warmup_pending = False
                    self.archive_browser_warmup_completion_text = completion_text
                    warmup_text = "Loading texture sidecar cache in the background..."
                    self.archive_tree.setEnabled(True)
                    self.archive_stats_label.setText(
                        f"{len(self.archive_entries):,} archive entries loaded. Texture sidecar cache is warming in the background."
                    )
                    self.archive_scan_progress_label.setText(
                        "Archive entries loaded. Texture sidecar cache is tracked in the compact status indicator."
                    )
                    self.archive_scan_progress_bar.setRange(0, 1)
                    self.archive_scan_progress_bar.setValue(1)
                    self.archive_scan_progress_bar.setFormat("Ready")
                    self._set_archive_sidecar_status(warmup_text)
                    self.set_status_message(warmup_text)
                    self.append_archive_log(warmup_text)
                else:
                    self.archive_sidecar_pending_start = False
                release_startup_after_render = bool(getattr(self, "_startup_splash_window", None) is not None)
                startup_release_requested = {"done": False}

                def _release_startup_after_archive_render() -> None:
                    if startup_release_requested["done"]:
                        return
                    startup_release_requested["done"] = True
                    self._update_startup_splash(completion_text, 1, 1)
                    _write_heartbeat("running")
                    self._release_startup_splash()

                on_archive_view_ready: Optional[Callable[[], None]] = None
                if release_startup_after_render:
                    on_archive_view_ready = lambda: QTimer.singleShot(0, _release_startup_after_archive_render)
                self._refresh_or_defer_archive_browser_view(
                    activate_tab=self._activate_archive_browser_on_scan_complete,
                    on_complete=on_archive_view_ready,
                )
                self._activate_archive_browser_on_scan_complete = False
                self._refresh_or_defer_research_archive_picker()
                self.archive_scan_progress_label.setText(completion_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(1)
                self.archive_scan_progress_bar.setFormat("Ready")
                self.set_status_message(completion_text)
                self.append_archive_log(completion_text)
                self._set_archive_warmup_overlay(False)
                if release_startup_after_render:
                    if not self.archive_tree_population_active and not self.archive_tree_category_population_active:
                        QTimer.singleShot(0, _release_startup_after_archive_render)
                else:
                    _write_heartbeat("running")
                    self._release_startup_splash()
            finally:
                self.archive_scan_finalize_pending = False
                if self.archive_derived_cache_write_pending:
                    QTimer.singleShot(0, self._start_archive_derived_index_cache_writer)
                if start_sidecar_after_finalize:
                    if self.worker_thread is None and self.archive_sidecar_thread is None:
                        QTimer.singleShot(0, self._start_archive_sidecar_index_worker)
                if self.worker_thread is None:
                    self.set_busy(False, build_mode=False)

        def _start_archive_derived_index_cache_writer(self) -> None:
            if self._shutting_down:
                self.archive_derived_cache_write_pending = False
                return
            if not self.archive_derived_cache_write_pending:
                return
            if self.archive_derived_cache_thread is not None:
                return
            if not self.archive_entries:
                self.archive_derived_cache_write_pending = False
                return
            package_root_text = self.archive_package_root_edit.text().strip()
            if not package_root_text:
                self.archive_derived_cache_write_pending = False
                return

            self.archive_derived_cache_write_pending = False
            worker = ArchiveDerivedIndexCacheWriteWorker(
                Path(package_root_text).expanduser(),
                self.archive_cache_root,
                self.archive_entries,
                item_search_aliases=self.archive_item_search_aliases,
                item_display_names=self.archive_item_display_names,
                item_exact_display_names=self.archive_item_exact_display_names,
                item_related_display_names=self.archive_item_related_display_names,
                item_asset_catalog=self.archive_item_asset_catalog,
                archive_name_search_index=self.archive_name_search_index,
            )
            thread = QThread(self)
            worker.moveToThread(thread)

            thread.started.connect(worker.run)
            worker.log_message.connect(self.append_log)
            worker.log_message.connect(self.append_archive_log)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            thread.finished.connect(self._cleanup_archive_derived_cache_refs)

            self.archive_derived_cache_worker = worker
            self.archive_derived_cache_thread = thread
            try:
                thread.start(QThread.LowPriority)
            except Exception:
                thread.start()

        def _cleanup_archive_derived_cache_refs(self) -> None:
            self.archive_derived_cache_thread = None
            self.archive_derived_cache_worker = None
            if self.archive_derived_cache_write_pending and not self._shutting_down:
                QTimer.singleShot(0, self._start_archive_derived_index_cache_writer)

        def _start_archive_sidecar_index_worker(self) -> None:
            if self._shutting_down:
                self.archive_sidecar_pending_start = False
                return
            if not self._current_archive_performance_settings().enable_sidecar_indexing:
                self.archive_sidecar_pending_start = False
                self.archive_browser_warmup_pending = False
                self.archive_tree.setEnabled(True)
                return
            if self.archive_sidecar_thread is not None:
                self.archive_sidecar_pending_start = True
                return
            if not self.archive_entries:
                self.archive_sidecar_pending_start = False
                return
            package_root_text = self.archive_package_root_edit.text().strip()
            if not package_root_text:
                self.archive_sidecar_pending_start = False
                return

            self.archive_sidecar_pending_start = False
            request_id = self.archive_sidecar_request_id + 1
            self.archive_sidecar_request_id = request_id
            self._archive_sidecar_last_ui_progress_at = 0.0
            self._archive_sidecar_last_ui_detail = ""
            package_root = Path(package_root_text).expanduser()

            if self.archive_browser_warmup_pending:
                progress_text = "Loading texture sidecar cache..."
            else:
                progress_text = "Checking texture sidecar cache in background..."
            if not self.archive_browser_warmup_pending:
                self.append_archive_log(progress_text)
            self.set_status_message(progress_text)
            self._set_archive_sidecar_status(progress_text)

            worker = ArchiveSidecarIndexWorker(
                request_id,
                package_root,
                self.archive_cache_root,
                self.archive_entries,
                sidecar_worker_count=self._current_archive_performance_settings().sidecar_worker_count,
            )
            thread = QThread(self)
            worker.moveToThread(thread)

            thread.started.connect(worker.run)
            worker.log_message.connect(self.append_log)
            worker.log_message.connect(self.append_archive_log)
            worker.progress_changed.connect(self._handle_archive_sidecar_progress)
            worker.completed.connect(self._handle_archive_sidecar_complete)
            worker.error.connect(self._handle_archive_sidecar_error)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            thread.finished.connect(self._cleanup_archive_sidecar_refs)

            self.archive_sidecar_worker = worker
            self.archive_sidecar_thread = thread
            try:
                if self.archive_browser_warmup_pending or self._current_archive_performance_settings().maximum_indexing_priority:
                    thread.start()
                else:
                    thread.start(QThread.LowPriority)
            except Exception:
                thread.start()

        def _compact_archive_sidecar_status_text(self, detail: str, elapsed: float) -> str:
            detail_text = str(detail or "").strip()
            lowered = detail_text.lower()
            if "checking" in lowered and "cache" in lowered:
                phase = "Checking"
            elif "loading" in lowered and "cache" in lowered:
                phase = "Loading"
            elif "indexing" in lowered or "sidecar files" in lowered:
                phase = "Indexing"
            elif "basename" in lowered:
                phase = "Basenames"
            elif "lazy" in lowered or "lookup" in lowered:
                phase = "Lookup"
            elif "writing" in lowered:
                phase = "Writing"
            elif "ready" in lowered or "loaded" in lowered or "indexed" in lowered:
                phase = "Ready"
            elif detail_text:
                phase = detail_text.split("...", 1)[0].split(".", 1)[0][:10].strip() or "Working"
            else:
                phase = "Working"
            elapsed_value = int(max(0.0, elapsed))
            if phase == "Ready":
                return "Sidecar: Ready"
            return f"{phase} {elapsed_value}s"

        def _set_archive_sidecar_status(self, detail: str, current: int = 0, total: int = 0) -> None:
            detail_text = str(detail or "Texture sidecar cache working...").strip()
            if not detail_text:
                detail_text = "Texture sidecar cache working..."
            if float(getattr(self, "_archive_sidecar_status_started_at", 0.0) or 0.0) <= 0.0:
                self._archive_sidecar_status_started_at = time.perf_counter()
            self._archive_sidecar_status_detail = detail_text
            self._archive_sidecar_status_current = max(0, int(current or 0))
            self._archive_sidecar_status_total = max(0, int(total or 0))
            self.archive_sidecar_status_widget.setVisible(True)
            if total > 0:
                completed_value = min(max(int(current), 0), int(total))
                self.archive_sidecar_status_bar.setRange(0, int(total))
                self.archive_sidecar_status_bar.setValue(completed_value)
            else:
                self.archive_sidecar_status_bar.setRange(0, 0)
            self._refresh_archive_sidecar_status_elapsed()
            if not self._archive_sidecar_status_timer.isActive():
                self._archive_sidecar_status_timer.start()

        def _refresh_archive_sidecar_status_elapsed(self) -> None:
            if not hasattr(self, "archive_sidecar_status_label"):
                return
            started_at = float(getattr(self, "_archive_sidecar_status_started_at", 0.0) or 0.0)
            if started_at <= 0.0:
                return
            detail = str(getattr(self, "_archive_sidecar_status_detail", "") or "Texture sidecar cache working...").strip()
            elapsed = max(0.0, time.perf_counter() - started_at)
            self.archive_sidecar_status_label.setText(self._compact_archive_sidecar_status_text(detail, elapsed))
            self.archive_sidecar_status_widget.setToolTip(f"Texture sidecar cache: {detail} ({elapsed:.0f}s)")

        def _finish_archive_sidecar_status(self, detail: str, *, success: bool = True) -> None:
            if not hasattr(self, "archive_sidecar_status_label"):
                return
            started_at = float(getattr(self, "_archive_sidecar_status_started_at", 0.0) or 0.0)
            elapsed = max(0.0, time.perf_counter() - started_at) if started_at > 0.0 else 0.0
            self._archive_sidecar_status_timer.stop()
            self._archive_sidecar_status_started_at = 0.0
            label = str(detail or "Texture sidecar cache complete.").strip()
            if elapsed > 0.0:
                label = f"{label} ({elapsed:.1f}s)"
            self.archive_sidecar_status_label.setText(self._compact_archive_sidecar_status_text(label, elapsed))
            self.archive_sidecar_status_widget.setToolTip(f"Texture sidecar cache: {label}")
            self.archive_sidecar_status_widget.setVisible(True)
            self.archive_sidecar_status_bar.setRange(0, 1)
            self.archive_sidecar_status_bar.setValue(1 if success else 0)

        def _handle_archive_sidecar_progress(self, request_id: int, current: int, total: int, detail: str) -> None:
            if self._shutting_down or request_id != self.archive_sidecar_request_id:
                return
            if self._utility_updates_archive_progress:
                return
            self._set_archive_sidecar_status(detail, current, total)
            now = time.perf_counter()
            last_update_at = float(getattr(self, "_archive_sidecar_last_ui_progress_at", 0.0) or 0.0)
            previous_detail = str(getattr(self, "_archive_sidecar_last_ui_detail", "") or "")
            force_phase_update = bool(total <= 0 and detail and detail != previous_detail)
            if not force_phase_update and (total <= 0 or current < total):
                if now - last_update_at < 0.75:
                    return
            self._archive_sidecar_last_ui_progress_at = now
            self._archive_sidecar_last_ui_detail = str(detail or "")
            if self.archive_entries and self.archive_browser_warmup_pending:
                self.archive_stats_label.setText(
                    f"{len(self.archive_entries):,} archive entries loaded. {detail}"
                )

        def _handle_archive_sidecar_complete(self, request_id: int, result: object) -> None:
            if self._shutting_down or request_id != self.archive_sidecar_request_id:
                return
            payload = result if isinstance(result, dict) else {}
            self.archive_sidecar_entries_by_texture_path = (
                payload.get("sidecar_entries_by_texture_path", {})
                if isinstance(payload.get("sidecar_entries_by_texture_path"), Mapping)
                else {}
            )
            self.archive_sidecar_entries_by_texture_basename = (
                payload.get("sidecar_entries_by_texture_basename", {})
                if isinstance(payload.get("sidecar_entries_by_texture_basename"), Mapping)
                else {}
            )
            source = str(payload.get("source", "scan")).strip().lower() or "scan"
            cache_path_text = str(payload.get("cache_path", "")).strip()
            timings = payload.get("timings", {}) if isinstance(payload.get("timings"), dict) else {}
            timing_summary = str(payload.get("timing_summary", "")).strip()
            total_seconds = _timing_value(timings, "total_s")
            elapsed_suffix = f" in {total_seconds:.1f}s" if total_seconds > 0 else ""
            completion_text = (
                f"Texture sidecar bindings loaded from cache{elapsed_suffix}."
                if source == "cache"
                else f"Texture sidecar bindings indexed{elapsed_suffix}."
            )
            if self.worker_thread is None and not self._utility_updates_archive_progress:
                self.archive_scan_progress_label.setText(completion_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(1)
                self.archive_scan_progress_bar.setFormat("Ready")
                self._set_archive_warmup_overlay(False)
            self._finish_archive_sidecar_status(completion_text, success=True)
            self.set_status_message(completion_text)
            self.append_archive_log(completion_text)
            if cache_path_text and source == "scan":
                self.append_archive_log(f"Texture sidecar cache ready: {cache_path_text}")
            if timing_summary:
                self.append_archive_log(timing_summary, verbose=True)
            sidecar_count = int(_timing_value(timings, "sidecar_count"))
            sidecar_group_count = int(_timing_value(timings, "sidecar_group_count"))
            sidecar_worker_count = int(_timing_value(timings, "sidecar_worker_count"))
            if sidecar_count > 0:
                self.append_archive_log(
                    "Texture sidecar scan detail: "
                    f"sidecars={sidecar_count:,} | paz_groups={sidecar_group_count:,} | workers={sidecar_worker_count:,}",
                    verbose=True,
                )
            if source == "cache" and _timing_value(timings, "total_s") > 1.0:
                self.append_archive_log(
                    f"WARNING: Texture sidecar cache hit is slower than expected: total={_timing_value(timings, 'total_s'):.2f}s.",
                    verbose=True,
                )

            self.archive_sidecar_generation += 1
            self._clear_archive_preview_cache()
            if self.archive_browser_warmup_pending:
                self.archive_browser_warmup_pending = False
                self.archive_tree.setEnabled(True)
                self._refresh_or_defer_archive_browser_view(
                    activate_tab=self._activate_archive_browser_on_scan_complete,
                )
                self._activate_archive_browser_on_scan_complete = False
                self._refresh_or_defer_research_archive_picker()
                completion_text = self.archive_browser_warmup_completion_text or (
                    f"Archive scan complete. Found {len(self.archive_entries):,} entries."
                )
                self.archive_browser_warmup_completion_text = ""
                self.archive_stats_label.setText(
                    f"{len(self.archive_entries):,} archive entries loaded. Texture sidecar cache ready."
                )
                self.archive_scan_progress_label.setText(completion_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(1)
                self.archive_scan_progress_bar.setFormat("Ready")
                self._set_archive_warmup_overlay(False)
                self.set_status_message(completion_text)
                self.append_archive_log(completion_text)
                if self.worker_thread is None:
                    self.set_busy(False, build_mode=False)
                return
            current_entry = self._current_archive_entry()
            current_result_generation = int(
                getattr(self.current_archive_preview_result, "sidecar_generation", -1)
                if self.current_archive_preview_result is not None
                else -1
            )
            if (
                current_entry is not None
                and self.archive_preview_thread is None
                and not self.archive_preview_showing_loose
                and (
                    self.current_archive_preview_result is None
                    or current_result_generation < self.archive_sidecar_generation
                    or not self.current_archive_model_texture_references
                )
            ):
                QTimer.singleShot(0, lambda entry=current_entry: self._render_archive_preview(entry))

        def _handle_archive_sidecar_error(self, request_id: int, message: str) -> None:
            if self._shutting_down or request_id != self.archive_sidecar_request_id:
                return
            error_text = f"Texture sidecar indexing failed: {message}"
            self.set_status_message(error_text, error=True)
            self.append_log(f"ERROR: {error_text}")
            self.append_archive_log(f"ERROR: {error_text}")
            if self.worker_thread is None and not self._utility_updates_archive_progress:
                self.archive_scan_progress_label.setText(error_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(0)
                self.archive_scan_progress_bar.setFormat("Ready")
            self._finish_archive_sidecar_status(error_text, success=False)
            self._set_archive_warmup_overlay(False)
            if self.archive_browser_warmup_pending:
                self.archive_browser_warmup_pending = False
                self.archive_tree.setEnabled(True)
                self._refresh_or_defer_archive_browser_view(
                    activate_tab=self._activate_archive_browser_on_scan_complete,
                )
                self._activate_archive_browser_on_scan_complete = False
                self._refresh_or_defer_research_archive_picker()
                if self.worker_thread is None:
                    self.set_busy(False, build_mode=False)

        def _cleanup_archive_sidecar_refs(self) -> None:
            self.archive_sidecar_thread = None
            self.archive_sidecar_worker = None
            if self._shutting_down:
                self.archive_sidecar_pending_start = False
                return
            if self.archive_sidecar_pending_start and self._current_archive_performance_settings().enable_sidecar_indexing:
                QTimer.singleShot(0, self._start_archive_sidecar_index_worker)
            else:
                self.archive_sidecar_pending_start = False

        def _current_archive_filter_signature(self) -> Tuple[object, ...]:
            return (
                self.archive_filter_edit.text().strip(),
                self.archive_exclude_filter_edit.text().strip(),
                normalize_archive_extension_filter(self._combo_value(self.archive_extension_filter_combo)),
                self.archive_package_filter_edit.text().strip(),
                self._current_archive_structure_filter_value(),
                self._combo_value(self.archive_role_filter_combo),
                bool(self.archive_exclude_common_technical_checkbox.isChecked()),
                int(self.archive_min_size_spin.value()),
                bool(self.archive_previewable_only_checkbox.isChecked()),
                self._archive_browser_view_mode(),
                int(self.archive_tree_sort_column),
                self.archive_tree_sort_order,
            )

        def _mark_archive_filters_dirty(self) -> None:
            self.archive_filters_dirty = True
            if self.archive_tree_clear_active:
                self._cancel_archive_tree_clear()
                pause_text = "Archive list update paused while filters are being edited. Press Apply Filters to refresh."
                self.archive_scan_progress_label.setText(pause_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(0)
                self.archive_scan_progress_bar.setFormat("Paused")
                self.set_status_message(pause_text)
            if self.archive_tree_population_active:
                self._cancel_archive_tree_population()
                pause_text = "Archive list update paused while filters are being edited. Press Apply Filters to refresh."
                self.archive_scan_progress_label.setText(pause_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(0)
                self.archive_scan_progress_bar.setFormat("Paused")
                self.set_status_message(pause_text)
            if self.archive_filter_worker is not None:
                try:
                    self.archive_filter_worker.stop()
                except Exception:
                    pass
            self._update_archive_filter_button_state()

        def _clear_archive_structure_filter_widgets(self) -> None:
            while self.archive_structure_filter_layout.count():
                item = self.archive_structure_filter_layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.deleteLater()

        def _current_archive_structure_filter_value(self) -> str:
            if not self.archive_structure_filter_combos:
                return normalize_archive_structure_filter_value(self.archive_structure_filter_pending_value)
            selected_value = ""
            for combo in self.archive_structure_filter_combos:
                value = normalize_archive_structure_filter_value(self._combo_value(combo))
                if not value or value == selected_value:
                    break
                selected_value = value
            return selected_value

        def _set_archive_structure_filter_enabled(self, enabled: bool) -> None:
            for combo in self.archive_structure_filter_combos:
                combo.setEnabled(enabled)

        def _format_archive_structure_combo_label(self, value: str, count: int) -> str:
            leaf = value.rsplit("/", 1)[-1]
            return f"{leaf}/ ({count:,})"

        def _rebuild_archive_structure_filter_controls(
            self,
            selected_value: Optional[str] = None,
            *,
            rebuild_children: bool = False,
        ) -> None:
            preferred_value = normalize_archive_structure_filter_value(
                selected_value
                if selected_value is not None
                else (self._current_archive_structure_filter_value() or self.archive_structure_filter_pending_value)
            )
            if rebuild_children or (not self.archive_structure_filter_children and self.archive_entries):
                self.archive_structure_filter_children = build_archive_structure_children_map(self.archive_entries)
            self.rebuilding_archive_structure_filters = True
            self._clear_archive_structure_filter_widgets()
            self.archive_structure_filter_combos = []

            if not self.archive_structure_filter_children:
                empty_label = QLabel("Scan archives to load folder filters.")
                empty_label.setObjectName("HintLabel")
                self.archive_structure_filter_layout.addWidget(empty_label)
                self.archive_structure_filter_layout.addStretch(1)
                self.archive_structure_filter_pending_value = preferred_value
                self.rebuilding_archive_structure_filters = False
                return

            segments = preferred_value.split("/") if preferred_value else []
            parent = ""
            level = 0
            while True:
                child_options = self.archive_structure_filter_children.get(parent, [])
                if not child_options:
                    break

                combo = QComboBox()
                combo.setMaxVisibleItems(30)
                combo.setMinimumWidth(170)
                if parent == "":
                    self._add_combo_choice(combo, "All packages", "")
                else:
                    self._add_combo_choice(combo, f"All in {parent.rsplit('/', 1)[-1]}/", parent)
                for child_value, count in child_options:
                    self._add_combo_choice(combo, self._format_archive_structure_combo_label(child_value, count), child_value)

                selected_child_value = ""
                if len(segments) > level:
                    candidate = "/".join(segments[: level + 1])
                    if combo.findData(candidate) >= 0:
                        selected_child_value = candidate
                self._set_combo_by_value(combo, selected_child_value if selected_child_value else (parent if parent else ""))
                combo.currentIndexChanged.connect(
                    lambda _index, level=level: self._handle_archive_structure_combo_changed(level)
                )
                combo.setEnabled(self.worker_thread is None)
                self.archive_structure_filter_layout.addWidget(combo)
                self.archive_structure_filter_combos.append(combo)

                if not selected_child_value:
                    break
                parent = selected_child_value
                level += 1

            self.archive_structure_filter_layout.addStretch(1)
            self.archive_structure_filter_pending_value = self._current_archive_structure_filter_value() or preferred_value
            self.rebuilding_archive_structure_filters = False

        def _handle_archive_structure_combo_changed(self, _level: int) -> None:
            if self.rebuilding_archive_structure_filters:
                return
            self.archive_structure_filter_pending_value = self._current_archive_structure_filter_value()
            self._rebuild_archive_structure_filter_controls(self.archive_structure_filter_pending_value)
            self._save_settings()
            self._mark_archive_filters_dirty()

        def _archive_browser_view_mode(self) -> str:
            mode = str(self._combo_value(self.archive_browser_view_mode_combo) or ARCHIVE_BROWSER_VIEW_MODE)
            return mode if mode in {"folders", "categories", "categories_folders", "flat"} else ARCHIVE_BROWSER_VIEW_MODE

        def _archive_tree_sort_active(self) -> bool:
            return archive_browser_sort_is_active(self.archive_tree_sort_column)

        def _update_archive_tree_sort_indicator(self) -> None:
            if not hasattr(self, "archive_tree"):
                return
            header = self.archive_tree.header()
            if header is None:
                return
            column = normalize_archive_browser_sort_column(self.archive_tree_sort_column)
            if column < 0:
                header.setSortIndicatorShown(False)
                return
            order = Qt.DescendingOrder if self.archive_tree_sort_order == "desc" else Qt.AscendingOrder
            header.setSortIndicator(column, order)
            header.setSortIndicatorShown(True)

        def _sort_current_archive_filtered_entries(self) -> None:
            if not self._archive_tree_sort_active():
                return
            self.archive_filtered_entries = sort_archive_entries_for_browser(
                self.archive_filtered_entries,
                self.archive_tree_sort_column,
                self.archive_tree_sort_order,
                item_display_names=self.archive_item_display_names,
                item_exact_display_names=self.archive_item_exact_display_names,
                item_related_display_names=self.archive_item_related_display_names,
                archive_entries_by_normalized_path=self.archive_entries_by_normalized_path,
            )

        def _rebuild_archive_browser_indexes_for_current_sort(self) -> None:
            self.archive_tree_category_entry_indexes = build_archive_category_entry_index(self.archive_filtered_entries)
            if self._archive_folder_tree_enabled():
                (
                    self.archive_tree_child_folders,
                    self.archive_tree_direct_files,
                    self.archive_tree_folder_entry_indexes,
                    self.archive_tree_folder_preview_stats,
                ) = build_archive_tree_index(
                    self.archive_filtered_entries,
                    preserve_direct_file_order=self._archive_tree_sort_active(),
                )
                self.archive_tree_index_ready = True
            else:
                self.archive_tree_child_folders = {}
                self.archive_tree_direct_files = {}
                self.archive_tree_folder_entry_indexes = {}
                self.archive_tree_folder_preview_stats = {}
                self.archive_tree_index_ready = False

        def _handle_archive_tree_header_clicked(self, column: int) -> None:
            column = normalize_archive_browser_sort_column(column)
            if column < 0:
                return
            current_entry = self._current_archive_entry()
            preferred_path = current_entry.path if current_entry is not None else ""
            if self.archive_tree_sort_column == column:
                self.archive_tree_sort_order = "desc" if self.archive_tree_sort_order != "desc" else "asc"
            else:
                self.archive_tree_sort_column = column
                self.archive_tree_sort_order = "asc"
            self._update_archive_tree_sort_indicator()
            self.schedule_settings_save()
            if self.worker_thread is not None:
                if self.archive_filter_worker is not None:
                    self.archive_filter_apply_pending = True
                    self.archive_filter_worker.stop()
                    self.archive_scan_progress_label.setText("Stopping previous archive filter before applying column sort...")
                    self.archive_scan_progress_bar.setRange(0, 0)
                    self.archive_scan_progress_bar.setFormat("Stopping...")
                else:
                    self.archive_browser_refresh_pending = True
                    self.set_status_message("Archive column sort will apply after the current task finishes.")
                return
            if not self.archive_entries and not self.archive_filtered_entries:
                return
            if self.archive_active_asset_catalog_scope:
                self._sort_current_archive_filtered_entries()
                self._rebuild_archive_browser_indexes_for_current_sort()
                self._populate_archive_tree(preferred_path, rebuild_index=False)
                return
            if self.archive_entries:
                self._start_archive_filter_worker(preferred_path)
            else:
                self._sort_current_archive_filtered_entries()
                self._rebuild_archive_browser_indexes_for_current_sort()
                self._populate_archive_tree(preferred_path, rebuild_index=False)

        def _archive_tree_view_enabled(self) -> bool:
            return self._archive_browser_view_mode() != "flat"

        def _archive_folder_tree_enabled(self) -> bool:
            return self._archive_browser_view_mode() in {"folders", "categories_folders"}

        def _archive_category_view_enabled(self) -> bool:
            return self._archive_browser_view_mode() in {"categories", "categories_folders"}

        def _archive_category_index_ready(self) -> bool:
            return sum(len(indexes) for indexes in self.archive_tree_category_entry_indexes.values()) == len(self.archive_filtered_entries)

        def _handle_archive_browser_view_mode_changed(self, _index: int) -> None:
            self._cancel_archive_tree_clear()
            self._cancel_archive_tree_population()
            self.archive_tree.setRootIsDecorated(self._archive_tree_view_enabled())
            if self.worker_thread is not None:
                self.archive_browser_refresh_pending = True
                return
            current_entry = self._current_archive_entry()
            current_entry_path = current_entry.path if current_entry is not None else ""
            rebuild_tree_index = bool(self._archive_folder_tree_enabled() and not self.archive_tree_index_ready and self.archive_filtered_entries)
            rebuild_category_index = bool(self._archive_category_view_enabled() and not self._archive_category_index_ready() and self.archive_filtered_entries)
            if (rebuild_tree_index or rebuild_category_index) and self.archive_entries:
                self._start_archive_filter_worker(current_entry_path)
                return
            self._populate_archive_tree(current_entry_path, rebuild_index=rebuild_tree_index)

        def _update_archive_filter_button_state(self) -> None:
            button_label = "Apply Filters*" if self.archive_filters_dirty else "Apply Filters"
            search_button_label = "Search*" if self.archive_filters_dirty else "Search"
            self.archive_filter_apply_button.setText(button_label)
            self.archive_path_search_button.setText(search_button_label)
            can_apply = self.worker_thread is None and self.archive_filters_dirty
            self.archive_filter_apply_button.setEnabled(can_apply)
            self.archive_path_search_button.setEnabled(self.worker_thread is None)
            self.archive_filter_clear_button.setEnabled(self.worker_thread is None)
            self.archive_asset_catalog_button.setEnabled(self.worker_thread is None and bool(self.archive_item_asset_catalog))
            self.archive_clear_asset_scope_button.setVisible(bool(self.archive_active_asset_catalog_scope))
            self.archive_clear_asset_scope_button.setEnabled(self.worker_thread is None and bool(self.archive_active_asset_catalog_scope))
            if hasattr(self, "archive_scope_banner_label"):
                scope_text = str(self.archive_active_asset_catalog_scope or "").strip()
                if scope_text:
                    self.archive_scope_banner_label.setText(
                        f"Scope active: {scope_text}. Clear Scope returns to normal archive filtering."
                    )
                    self.archive_scope_banner_label.setVisible(True)
                else:
                    self.archive_scope_banner_label.clear()
                    self.archive_scope_banner_label.setVisible(False)

        def _clear_archive_filters(self) -> None:
            self.archive_active_asset_catalog_scope = ""
            self.archive_clear_asset_scope_button.setVisible(False)
            if hasattr(self, "archive_scope_banner_label"):
                self.archive_scope_banner_label.clear()
                self.archive_scope_banner_label.setVisible(False)
            self.archive_filter_edit.setPlaceholderText("Include path/item-name filter or glob, e.g. Vow of the Dead King or */texture/*")
            self.archive_filter_edit.clear()
            self.archive_exclude_filter_edit.clear()
            self._set_combo_by_value(self.archive_extension_filter_combo, ARCHIVE_EXTENSION_FILTER)
            self.archive_package_filter_edit.clear()
            self.archive_structure_filter_pending_value = ARCHIVE_STRUCTURE_FILTER
            self._rebuild_archive_structure_filter_controls(ARCHIVE_STRUCTURE_FILTER)
            self._set_combo_by_value(self.archive_role_filter_combo, ARCHIVE_ROLE_FILTER)
            self.archive_exclude_common_technical_checkbox.setChecked(ARCHIVE_EXCLUDE_COMMON_TECHNICAL_SUFFIXES)
            self.archive_min_size_spin.setValue(ARCHIVE_MIN_SIZE_KB)
            self.archive_previewable_only_checkbox.setChecked(ARCHIVE_PREVIEWABLE_ONLY)
            self._set_combo_by_value(self.archive_browser_view_mode_combo, ARCHIVE_BROWSER_VIEW_MODE)
            self.archive_package_filter_hint_label.setText("Exclude accepts semicolon-separated substrings or globs.")
            self._save_settings()
            self._apply_archive_filter()

        def _clear_archive_asset_catalog_scope(self) -> None:
            if not self.archive_active_asset_catalog_scope:
                return
            self.archive_active_asset_catalog_scope = ""
            self.archive_clear_asset_scope_button.setVisible(False)
            if hasattr(self, "archive_scope_banner_label"):
                self.archive_scope_banner_label.clear()
                self.archive_scope_banner_label.setVisible(False)
            self.archive_filter_edit.setPlaceholderText("Include path/item-name filter or glob, e.g. Vow of the Dead King or */texture/*")
            self.archive_filter_edit.clear()
            self.archive_package_filter_hint_label.setText("Exclude accepts semicolon-separated substrings or globs.")
            self._apply_archive_filter()

        def _apply_archive_filter(self) -> None:
            if self.archive_active_asset_catalog_scope:
                self.archive_active_asset_catalog_scope = ""
                self.archive_clear_asset_scope_button.setVisible(False)
                if hasattr(self, "archive_scope_banner_label"):
                    self.archive_scope_banner_label.clear()
                    self.archive_scope_banner_label.setVisible(False)
                self.archive_filter_edit.setPlaceholderText("Include path/item-name filter or glob, e.g. Vow of the Dead King or */texture/*")
                self.archive_package_filter_hint_label.setText("Exclude accepts semicolon-separated substrings or globs.")
            self._cancel_archive_tree_clear()
            self._cancel_archive_tree_population()
            self.pending_archive_preview_request = None
            self.scheduled_archive_preview_request = None
            self.archive_preview_debounce_timer.stop()
            self._stop_archive_native_preview_prefetch()
            if self.archive_preview_worker is not None:
                try:
                    self.archive_preview_worker.stop()
                except Exception:
                    pass
            self._stop_archive_preview_loading_indicator(success=None)
            if self.worker_thread is not None:
                if self.archive_filter_worker is not None:
                    self.archive_filter_apply_pending = True
                    self.archive_filter_worker.stop()
                    self.archive_scan_progress_label.setText("Stopping previous archive filter...")
                    self.archive_scan_progress_bar.setRange(0, 0)
                    self.archive_scan_progress_bar.setFormat("Stopping...")
                    self.set_status_message("Stopping previous archive filter...")
                return
            if not self.archive_entries:
                self.archive_filtered_entries = []
                self.archive_filtered_dds_count = 0
                self.archive_tree_category_entry_indexes = {}
                self.archive_filters_dirty = False
                self._update_archive_filter_button_state()
                self._populate_archive_tree("")
                self._refresh_or_defer_research_archive_picker()
                return
            current_entry = self._current_archive_entry()
            current_entry_path = current_entry.path if current_entry is not None else ""
            self._start_archive_filter_worker(current_entry_path)

        def _start_archive_filter_worker(
            self,
            preferred_path: str = "",
            *,
            build_category_index: Optional[bool] = None,
        ) -> None:
            filter_text = self.archive_filter_edit.text().strip()
            exclude_filter_text = self.archive_exclude_filter_edit.text().strip()
            extension_filter = self._combo_value(self.archive_extension_filter_combo)
            package_filter_text = self.archive_package_filter_edit.text().strip()
            structure_filter = self._current_archive_structure_filter_value()
            self.archive_structure_filter_pending_value = structure_filter
            role_filter = self._combo_value(self.archive_role_filter_combo)
            exclude_common_technical_suffixes = self.archive_exclude_common_technical_checkbox.isChecked()
            min_size_kb = self.archive_min_size_spin.value()
            previewable_only = self.archive_previewable_only_checkbox.isChecked()
            if build_category_index is None:
                build_category_index = self._archive_category_view_enabled()
            request_signature = self._current_archive_filter_signature()
            self.archive_filter_requested_signature = request_signature
            self.archive_filter_apply_pending = False
            self.archive_scan_progress_label.setText("Preparing archive filter...")
            self.archive_scan_progress_bar.setRange(0, 0)
            self.archive_scan_progress_bar.setFormat("Working...")
            self.set_status_message("Applying archive filters...")
            self.append_archive_log("Applying archive filters...")

            worker = ArchiveFilterWorker(
                self.archive_entries,
                entries_by_extension=self.archive_entries_by_extension,
                entries_by_normalized_path=self.archive_entries_by_normalized_path,
                entries_by_basename=self.archive_entries_by_basename,
                archive_name_search_index=self.archive_name_search_index,
                request_signature=request_signature,
                preferred_path=preferred_path,
                build_tree_index=self._archive_folder_tree_enabled(),
                filter_text=filter_text,
                exclude_filter_text=exclude_filter_text,
                extension_filter=extension_filter,
                package_filter_text=package_filter_text,
                structure_filter=structure_filter,
                role_filter=role_filter,
                exclude_common_technical_suffixes=exclude_common_technical_suffixes,
                min_size_kb=min_size_kb,
                previewable_only=previewable_only,
                build_category_index=bool(build_category_index),
                item_search_aliases=self.archive_item_search_aliases,
                item_display_names=self.archive_item_display_names,
                item_exact_display_names=self.archive_item_exact_display_names,
                item_related_display_names=self.archive_item_related_display_names,
                sort_column=self.archive_tree_sort_column,
                sort_order=self.archive_tree_sort_order,
            )
            thread = QThread(self)
            worker.moveToThread(thread)

            thread.started.connect(worker.run)
            worker.progress_changed.connect(self._handle_archive_scan_progress)
            worker.completed.connect(self._handle_archive_filter_complete)
            worker.error.connect(self._handle_worker_error)
            worker.finished.connect(thread.quit)
            worker.finished.connect(worker.deleteLater)
            thread.finished.connect(thread.deleteLater)
            thread.finished.connect(self._cleanup_worker_refs)

            self.archive_filter_worker = worker
            self.worker_thread = thread
            self.set_busy(True, build_mode=False)
            thread.start()

        def _handle_archive_filter_complete(self, result: object) -> None:
            self._flush_archive_scan_progress()
            payload = result if isinstance(result, dict) else {}
            browser_state = payload.get("browser_state") if isinstance(payload.get("browser_state"), dict) else {}
            request_signature = tuple(payload.get("request_signature") or ())
            preferred_path = str(payload.get("preferred_path", "") or "").strip()
            if request_signature and request_signature != self._current_archive_filter_signature():
                self.archive_filters_dirty = True
                self._update_archive_filter_button_state()
                stale_text = "Archive filter inputs changed while results were still loading. Press Apply Filters to refresh."
                self.archive_scan_progress_label.setText(stale_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(0)
                self.archive_scan_progress_bar.setFormat("Stale")
                self.set_status_message(stale_text)
                return
            self.archive_filtered_entries = (
                browser_state.get("filtered_entries", [])
                if isinstance(browser_state.get("filtered_entries"), list)
                else []
            )
            self.archive_tree_child_folders = (
                browser_state.get("tree_child_folders", {})
                if isinstance(browser_state.get("tree_child_folders"), dict)
                else {}
            )
            self.archive_tree_direct_files = (
                browser_state.get("tree_direct_files", {})
                if isinstance(browser_state.get("tree_direct_files"), dict)
                else {}
            )
            self.archive_tree_folder_entry_indexes = (
                browser_state.get("tree_folder_entry_indexes", {})
                if isinstance(browser_state.get("tree_folder_entry_indexes"), dict)
                else {}
            )
            self.archive_tree_folder_preview_stats = (
                browser_state.get("tree_folder_preview_stats", {})
                if isinstance(browser_state.get("tree_folder_preview_stats"), dict)
                else {}
            )
            self.archive_tree_category_entry_indexes = (
                browser_state.get("category_entry_indexes", {})
                if isinstance(browser_state.get("category_entry_indexes"), dict)
                else {}
            )
            self.archive_tree_index_ready = bool(browser_state.get("tree_index_ready", True))
            self.archive_tree_items_by_folder_key = {}
            self.archive_filtered_dds_count = int(browser_state.get("dds_count", 0))
            self.archive_filters_dirty = False
            self._update_archive_filter_button_state()
            self.archive_scan_progress_label.setText("Rendering archive browser view...")
            self.archive_scan_progress_bar.setRange(0, 0)
            self.archive_scan_progress_bar.setFormat("Rendering...")
            self._set_archive_warmup_overlay(
                True,
                "Preparing Archive Browser View",
                (
                    "Rendering the browser from the prepared cache. Large flat views are capped so the app stays responsive; "
                    "use filters or Folders view for very broad result sets."
                ),
                fmt="Rendering...",
            )
            self.set_status_message("Rendering archive browser view...")
            QTimer.singleShot(
                0,
                lambda preferred_path=preferred_path: self._finalize_archive_filter_complete(preferred_path),
            )

        def _finalize_archive_filter_complete(self, preferred_path: str) -> None:
            def finish_filter_render() -> None:
                self._refresh_or_defer_research_archive_picker()
                filtered_entries = len(self.archive_filtered_entries)
                completion_text = f"Applied archive filters. Showing {filtered_entries:,} entries."
                self.archive_scan_progress_label.setText(completion_text)
                self.archive_scan_progress_bar.setRange(0, 1)
                self.archive_scan_progress_bar.setValue(1)
                self.archive_scan_progress_bar.setFormat("Ready")
                self._set_archive_warmup_overlay(False)
                self.set_status_message(completion_text)
                self.append_archive_log(completion_text)

            defer_default_selection = bool(getattr(self, "archive_startup_autoload_defer_preview", False))
            self.archive_startup_autoload_defer_preview = False
            self._populate_archive_tree(
                preferred_path,
                rebuild_index=False,
                on_complete=finish_filter_render,
                defer_default_selection=defer_default_selection,
            )

        def _archive_tree_item_kind(self, item: Optional[QTreeWidgetItem]) -> str:
            if item is None:
                return ""
            raw = item.data(0, Qt.UserRole)
            return raw if isinstance(raw, str) else ""

        def _archive_tree_item_value(self, item: Optional[QTreeWidgetItem]) -> object:
            if item is None:
                return None
            return item.data(0, Qt.UserRole + 1)

        def _archive_tree_folder_key(self, item: Optional[QTreeWidgetItem]) -> Tuple[str, ...]:
            raw = self._archive_tree_item_value(item)
            return raw if isinstance(raw, tuple) else ()

        def _archive_entry_display_size(self, entry: ArchiveEntry) -> Tuple[str, str]:
            original_text = format_byte_size(entry.orig_size)
            stored_text = format_byte_size(entry.comp_size)
            if int(entry.orig_size) == int(entry.comp_size):
                size_text = original_text
            else:
                size_text = f"{original_text} / {stored_text} stored"
            tooltip = f"Original: {int(entry.orig_size):,} bytes\nStored: {int(entry.comp_size):,} bytes"
            return size_text, tooltip

        def _archive_entry_category(self, entry: ArchiveEntry) -> str:
            return archive_browser_entry_category(entry)

        def _archive_entry_role_label(self, entry: Optional[ArchiveEntry]) -> str:
            if not isinstance(entry, ArchiveEntry):
                return "Unknown"
            ext = str(entry.extension or "").lower()
            path = str(entry.path or "").replace("\\", "/").lower()
            basename = PurePosixPath(path).name
            if ext in ARCHIVE_IMAGE_EXTENSIONS:
                return "Texture"
            if _is_material_sidecar_extension(ext, basename) or ext in {".pac_xml", ".pam_xml", ".pamlod_xml"}:
                return "Material"
            if ext in {".hkx", ".hkt"}:
                if "meshphysics" in path or "havokphysics" in path or "ragdoll" in path or "physics" in path:
                    return "Physics"
                return "HKX"
            if ext == ".paa_metabin":
                return "Animation Metadata"
            if ext in {".paa", ".motionblending", ".pae", ".paem", ".papr", ".paseq", ".paschedule", ".paschedulepath", ".pastage"}:
                return "Animation"
            if ext == ".pab":
                return "Skeleton / Rig"
            if ext in {".prefab", ".prefabdata_xml", ".prefabdata.xml", ".pappt"}:
                return "Prefab"
            if ext == ".pamhc":
                return "Model Property Metadata"
            if ext == ".seqmt":
                return "Sequence Texture Metadata"
            if ext in ARCHIVE_AUDIO_EXTENSIONS:
                return "Audio"
            if ext in ARCHIVE_VIDEO_EXTENSIONS:
                return "Video"
            if ext in ARCHIVE_TEXT_EXTENSIONS or ext in {".meshinfo", ".motionblending", ".paa_metabin", ".prefab", ".pappt", ".pamhc", ".seqmt"}:
                if "/ui" in path or path.startswith("ui/"):
                    return "UI"
                return "Metadata"
            if ext in {".pac", ".pam", ".pamlod", ".obj", ".fbx", ".dae", ".gltf", ".glb", ".mesh", ".mdl", ".model", ".pat", ".patx"}:
                return "Mesh"
            if "/ui" in path or path.startswith("ui/"):
                return "UI"
            return "Unknown"

        def _archive_role_display_text(self, entry: Optional[ArchiveEntry]) -> str:
            if not isinstance(entry, ArchiveEntry):
                return "Unknown"
            role = self._archive_entry_role_label(entry)
            extension = str(entry.extension or "").lower()
            return f"{role} {extension}".strip()

        def _archive_entry_override_state(self, entry: Optional[ArchiveEntry]) -> Tuple[str, str]:
            if not isinstance(entry, ArchiveEntry):
                return "", ""
            normalized_path = str(entry.path or "").replace("\\", "/").strip().lower()
            same_path_entries = list(self.archive_entries_by_normalized_path.get(normalized_path, ()))
            if not same_path_entries:
                same_path_entries = [entry]
            is_mod_package = archive_entry_is_mod_package(entry)
            if len(same_path_entries) <= 1:
                if is_mod_package:
                    return (
                        "Mod-added",
                        "This file comes from a mod/DMM-style package and no vanilla duplicate with the same virtual path was found.",
                    )
                return "", ""
            active_entry = active_archive_entry_for_virtual_path(same_path_entries) or entry
            active_key = archive_entry_identity_key(active_entry)
            current_key = archive_entry_identity_key(entry)
            active_label = str(getattr(active_entry, "package_label", "") or "").strip() or str(active_entry.pamt_path)
            duplicate_labels = [
                str(getattr(candidate, "package_label", "") or "").strip() or str(candidate.pamt_path)
                for candidate in sorted(same_path_entries, key=archive_entry_load_priority, reverse=True)
            ]
            duplicate_text = "\n".join(f"- {label}" for label in duplicate_labels[:12])
            if current_key == active_key:
                state = "Active mod" if archive_entry_is_mod_package(entry) else "Active original"
                return (
                    state,
                    "This duplicate is the active winner for this virtual path based on package/load priority.\n"
                    f"Active package: {active_label}\n"
                    f"Duplicate candidates:\n{duplicate_text}",
                )
            state = "Shadowed mod" if is_mod_package else "Shadowed original"
            return (
                state,
                "This duplicate is shadowed by a higher-priority archive entry with the same virtual path.\n"
                f"Active package: {active_label}\n"
                f"Duplicate candidates:\n{duplicate_text}",
            )

        def _archive_preview_health_text(
            self,
            result: Optional[ArchivePreviewResult],
            entry: Optional[ArchiveEntry],
            references: Sequence[ArchiveModelTextureReference] = (),
        ) -> str:
            if not isinstance(entry, ArchiveEntry):
                return ""
            parts: List[str] = []
            if isinstance(result, ArchivePreviewResult):
                status = str(getattr(result, "status", "") or "").strip().lower()
                preferred_view = str(getattr(result, "preferred_view", "") or "").strip().lower()
                if status == "ok":
                    parts.append("Preview OK" if preferred_view and preferred_view != "info" else "Readable")
                elif status:
                    parts.append(status.replace("_", " ").title())
                preview_model = getattr(result, "preview_model", None)
                if preview_model is not None:
                    parts.append("3D Preview")
            role = self._archive_entry_role_label(entry)
            if role:
                parts.append(role)
            reference_roles = {
                self._archive_reference_role_label(reference)
                for reference in references
                if isinstance(reference, ArchiveModelTextureReference)
            }
            if "Texture" in reference_roles:
                has_partial_texture = any(
                    "partial" in self._archive_texture_reference_status_text(reference).casefold()
                    for reference in references
                    if isinstance(reference, ArchiveModelTextureReference)
                    and self._archive_reference_role_label(reference) == "Texture"
                )
                parts.append("Textures Partial" if has_partial_texture else "Textures Linked")
            if "Material" in reference_roles:
                parts.append("Material Linked")
            if "Physics" in reference_roles or "HKX" in reference_roles:
                parts.append("Physics Linked")
            if self._archive_known_used_by_references(entry):
                parts.append("Used By Known Index")
            exact_name, name_hint, _name_reason = self._archive_entry_item_name_match(entry)
            if exact_name:
                parts.append("Name Exact")
            elif name_hint:
                parts.append("Name Inferred")
            if entry.extension in {".hkx", ".hkt"}:
                parts.append("Editable HKX/HKT" if role in {"Physics", "HKX"} else "HKX/HKT")
            seen: set[str] = set()
            ordered: List[str] = []
            for part in parts:
                normalized = part.casefold()
                if part and normalized not in seen:
                    ordered.append(part)
                    seen.add(normalized)
            return self._ui_compact_status_line(ordered)

        @staticmethod
        def _ui_compact_status_line(parts: Sequence[object]) -> str:
            seen: set[str] = set()
            ordered: List[str] = []
            for raw_part in parts:
                part = str(raw_part or "").strip()
                normalized = part.casefold()
                if part and normalized not in seen:
                    ordered.append(part)
                    seen.add(normalized)
            return "  |  ".join(ordered)

        @staticmethod
        def _ui_evidence_label(value: object) -> str:
            key = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
            labels = {
                "fixup_backed": "Fixup-backed",
                "ptch": "Fixup-backed",
                "exact": "Exact",
                "declared_owner_array": "Owner-array",
                "owner_array": "Owner-array",
                "typed_layout": "Typed layout",
                "inferred": "Inferred",
                "spatial_fallback": "Spatial fallback",
                "raw_observation": "Raw context",
                "descriptor_context": "Context hint",
                "strong_inference": "Strong inference",
                "generated_from_current_xml": "Generated",
                "experimental": "Experimental",
            }
            return labels.get(key, str(value or "").replace("_", " ").strip().title() or "Evidence")

        @staticmethod
        def _ui_risk_color(value: object) -> QColor:
            key = str(value or "").strip().casefold()
            if key in {"safe", "low", "patchable", "exact", "sidecar", "selected", "model ok", "resolved"} or "safe" in key:
                return QColor("#86efac")
            if key in {"medium", "inferred", "context only", "partial", "same stem", "path hint", "name hint", "prefab"} or "inferred" in key:
                return QColor("#fde68a")
            if key in {"high", "experimental", "mostly read-only", "missing", "unresolved"} or "high" in key or "experimental" in key:
                return QColor("#fca5a5")
            return QColor("#cbd5e1")

        def _ui_style_status_columns(self, item: QTreeWidgetItem, values_by_column: Mapping[int, object]) -> None:
            for column, value in values_by_column.items():
                item.setForeground(int(column), QBrush(self._ui_risk_color(value)))

        @staticmethod
        def _archive_role_color(role: str) -> QColor:
            normalized = str(role or "").casefold()
            if "texture" in normalized:
                return QColor("#93c5fd")
            if "material" in normalized:
                return QColor("#f9a8d4")
            if "physics" in normalized or "hkx" in normalized:
                return QColor("#fbbf24")
            if "skeleton" in normalized or "rig" in normalized:
                return QColor("#c4b5fd")
            if "prefab" in normalized or "metadata" in normalized:
                return QColor("#67e8f9")
            if "mesh" in normalized:
                return QColor("#86efac")
            if "audio" in normalized or "video" in normalized:
                return QColor("#fdba74")
            if "ui" in normalized:
                return QColor("#a7f3d0")
            return QColor("#cbd5e1")

        def _style_archive_role_columns(self, item: QTreeWidgetItem, role: str, *columns: int) -> None:
            color = self._archive_role_color(role)
            for column in columns:
                item.setForeground(column, QBrush(color))

        @staticmethod
        def _archive_override_state_color(state: str) -> QColor:
            normalized = str(state or "").casefold()
            if "active mod" in normalized or "mod-added" in normalized:
                return QColor("#86efac")
            if "active original" in normalized:
                return QColor("#93c5fd")
            if "shadowed" in normalized:
                return QColor("#fca5a5")
            return QColor("#8b949e")

        def _style_archive_override_state_column(self, item: QTreeWidgetItem, state: str, column: int) -> None:
            item.setForeground(column, QBrush(self._archive_override_state_color(state)))
            if str(state or "").casefold().startswith("active"):
                font = item.font(column)
                font.setBold(True)
                item.setFont(column, font)

        def _archive_entry_model_base_key_matches(self, entry: ArchiveEntry) -> Tuple[Tuple[str, str], ...]:
            stem = PurePosixPath(entry.basename.replace("\\", "/")).stem.strip().lower()
            if not stem:
                return ()
            matches: List[Tuple[str, str]] = []
            seen: set[str] = set()

            def add(key: str, relation: str) -> None:
                normalized_key = str(key or "").strip().lower()
                if normalized_key and normalized_key not in seen:
                    matches.append((normalized_key, relation))
                    seen.add(normalized_key)

            add(stem, "exact")
            grouped_stem = derive_texture_group_key(entry.basename).strip().lower()
            if grouped_stem:
                add(grouped_stem, "related")
            family_stem = _strip_archive_model_family_variant_suffix(stem)
            if family_stem:
                add(family_stem, "related")
            for alias_stem in iter_archive_character_equipment_root_alias_stems(stem):
                add(alias_stem, "related")
            for alias_stem in iter_archive_equipment_model_alias_stems(stem):
                add(alias_stem, "related")
            return tuple(matches)

        def _archive_entry_item_name_match(self, entry: ArchiveEntry) -> Tuple[str, str, str]:
            first_related_name = ""
            first_related_reason = ""
            for key, relation in self._archive_entry_model_base_key_matches(entry):
                exact_display_name = str(self.archive_item_exact_display_names.get(key, "") or "").strip()
                if relation == "exact" and exact_display_name:
                    return (
                        exact_display_name,
                        "Exact localization",
                        "Exact item name: ItemInfo._itemName localization resolved through ItemInfo._prefabDataList model/prefab evidence.",
                    )

                related_display_name = str(self.archive_item_related_display_names.get(key, "") or "").strip()
                if not related_display_name and relation == "related":
                    related_display_name = exact_display_name
                if not related_display_name:
                    related_display_name = str(self.archive_item_display_names.get(key, "") or "").strip()
                if related_display_name and not first_related_name:
                    first_related_name = related_display_name
                    first_related_reason = (
                        "Possible related item name. This is a navigation hint from a model family, variant, texture group, "
                        "equipment alias, icon reference, or related asset expansion; it is not proof that this file is that item."
                    )
            if first_related_name:
                return "", f"Name hint: {first_related_name}", first_related_reason
            return "", "", ""

        def _archive_asset_catalog_table_evidence_labels(self, row: Mapping[str, object]) -> Tuple[str, ...]:
            raw_values = row.get("table_evidence")
            if not isinstance(raw_values, Sequence) or isinstance(raw_values, (str, bytes, bytearray)):
                return ()
            labels: List[str] = []
            seen: set[str] = set()
            for value in raw_values:
                label = ""
                target = ""
                if isinstance(value, Mapping):
                    label = str(value.get("label", "") or "").strip()
                    if not label:
                        table = str(value.get("source_table", "") or "").strip()
                        field = str(value.get("source_field", "") or "").strip()
                        label = f"{table}.{field}" if table and field else table or field
                    target = str(value.get("target", "") or "").strip()
                else:
                    label = str(value or "").strip()
                if label and label not in seen:
                    labels.append(label)
                    seen.add(label)
                if target and target not in seen:
                    labels.append(target)
                    seen.add(target)
            return tuple(labels)

        def _archive_asset_catalog_text(self, row: Mapping[str, object]) -> str:
            values: List[str] = []
            for key in (
                "display_name",
                "internal_name",
                "category",
                "group",
                "evidence",
                "category_evidence",
                "scope_filter",
            ):
                value = row.get(key)
                if value:
                    values.append(str(value))
            values.extend(self._archive_asset_catalog_table_evidence_labels(row))
            for key in ("pac_files", "model_stems", "icon_paths", "localized_names", "compatibility_tags"):
                raw_values = row.get(key)
                if isinstance(raw_values, Sequence) and not isinstance(raw_values, (str, bytes, bytearray)):
                    values.extend(str(value) for value in raw_values if value)
            return " ".join(values).lower()

        def _build_archive_asset_catalog_icon(self, category: str, label: str = "") -> QIcon:
            key = str(category or "Item").strip().lower()
            colors = {
                "weapon": ("#ff9f43", "#3b2412"),
                "armor": ("#4aa3ff", "#122538"),
                "accessory": ("#f6c177", "#35260f"),
                "mount / pet": ("#6bd17d", "#142d1a"),
                "material": ("#c5a3ff", "#251939"),
                "consumable": ("#7ee787", "#112b1a"),
                "crafting / recipe": ("#8bd3dd", "#102b32"),
                "tool": ("#ffd166", "#3b3214"),
                "character customization": ("#ffb3c6", "#351620"),
                "gimmick / interactive": ("#ff7b72", "#351514"),
                "housing / prop": ("#a7c957", "#23300f"),
                "quest / document": ("#f28482", "#351919"),
                "progression / reward": ("#d0bfff", "#251a3a"),
                "item": ("#9fb3c8", "#17212b"),
            }
            fg, bg = colors.get(key, colors["item"])
            pixmap = QPixmap(34, 34)
            pixmap.fill(Qt.transparent)
            painter = QPainter(pixmap)
            painter.setRenderHint(QPainter.Antialiasing, True)
            painter.setPen(QPen(QColor(fg), 1.4))
            painter.setBrush(QColor(bg))
            painter.drawRoundedRect(2, 2, 30, 30, 6, 6)
            painter.setBrush(QColor(fg))
            if key == "weapon":
                path = QPainterPath()
                path.moveTo(23, 6)
                path.lineTo(28, 11)
                path.lineTo(13, 26)
                path.lineTo(9, 22)
                path.closeSubpath()
                painter.drawPath(path)
                painter.drawRect(7, 23, 10, 3)
            elif key == "armor":
                path = QPainterPath()
                path.moveTo(17, 7)
                path.lineTo(26, 11)
                path.lineTo(23, 27)
                path.lineTo(11, 27)
                path.lineTo(8, 11)
                path.closeSubpath()
                painter.drawPath(path)
            elif key == "mount / pet":
                painter.drawEllipse(QRectF(8, 11, 18, 13))
                painter.drawEllipse(QRectF(20, 8, 7, 7))
                painter.drawRect(9, 22, 4, 6)
                painter.drawRect(20, 22, 4, 6)
            elif key == "material":
                painter.drawEllipse(QRectF(8, 8, 18, 18))
                painter.setBrush(QColor(bg))
                painter.drawEllipse(QRectF(13, 13, 8, 8))
            elif key == "tool":
                painter.drawRect(9, 21, 17, 4)
                painter.drawRect(20, 8, 4, 17)
            elif key == "quest / document":
                painter.drawRect(10, 7, 15, 20)
                painter.setPen(QPen(QColor(bg), 1.2))
                painter.drawLine(13, 13, 22, 13)
                painter.drawLine(13, 18, 22, 18)
            else:
                letter = (str(label or category or "I").strip()[:1] or "I").upper()
                painter.setPen(QColor(fg))
                font = QFont(painter.font())
                font.setBold(True)
                font.setPointSize(13)
                painter.setFont(font)
                painter.drawText(QRectF(2, 2, 30, 30), Qt.AlignCenter, letter)
            painter.end()
            return QIcon(pixmap)

        def _archive_asset_catalog_icon_cache_key(
            self,
            row: Mapping[str, object],
            size: int,
        ) -> Tuple[Tuple[str, ...], int, str]:
            icon_paths = tuple(self._archive_asset_catalog_row_values(row, "icon_paths"))
            texconv_key = self.texconv_path_edit.text().strip()
            return icon_paths, max(1, int(size)), texconv_key

        def _clear_archive_asset_catalog_icon_cache(self) -> None:
            self.archive_item_icon_preload_timer.stop()
            self.archive_item_icon_preload_queue.clear()
            self.archive_item_icon_preload_next_index = 0
            self.archive_item_icon_pixmap_cache.clear()

        def _cached_archive_asset_catalog_inventory_icon_pixmap(
            self,
            row: Mapping[str, object],
            size: int = 48,
        ) -> Tuple[Optional[QPixmap], str]:
            cache_key = self._archive_asset_catalog_icon_cache_key(row, size)
            icon_paths, requested_size, texconv_key = cache_key
            if not icon_paths:
                return None, "No recovered inventory icon could be resolved for this row."
            cached = self.archive_item_icon_pixmap_cache.get(cache_key)
            if cached is not None:
                self.archive_item_icon_pixmap_cache.move_to_end(cache_key)
                return cached
            negative_note = ""
            for (cached_icon_paths, _cached_size, cached_texconv_key), cached_value in reversed(
                self.archive_item_icon_pixmap_cache.items()
            ):
                if cached_icon_paths != icon_paths or cached_texconv_key != texconv_key:
                    continue
                cached_pixmap, cached_note = cached_value
                if cached_pixmap is None or cached_pixmap.isNull():
                    if cached_note and not negative_note:
                        negative_note = cached_note
                    continue
                scaled_value = (
                    cached_pixmap.scaled(requested_size, requested_size, Qt.KeepAspectRatio, Qt.SmoothTransformation),
                    cached_note,
                )
                self.archive_item_icon_pixmap_cache[cache_key] = scaled_value
                self.archive_item_icon_pixmap_cache.move_to_end(cache_key)
                while len(self.archive_item_icon_pixmap_cache) > 1600:
                    self.archive_item_icon_pixmap_cache.popitem(last=False)
                return scaled_value
            if negative_note:
                result = (None, negative_note)
                self.archive_item_icon_pixmap_cache[cache_key] = result
                self.archive_item_icon_pixmap_cache.move_to_end(cache_key)
                while len(self.archive_item_icon_pixmap_cache) > 1600:
                    self.archive_item_icon_pixmap_cache.popitem(last=False)
                return result
            result = self._archive_asset_catalog_inventory_icon_pixmap(row, requested_size)
            self.archive_item_icon_pixmap_cache[cache_key] = result
            self.archive_item_icon_pixmap_cache.move_to_end(cache_key)
            while len(self.archive_item_icon_pixmap_cache) > 1600:
                self.archive_item_icon_pixmap_cache.popitem(last=False)
            return result

        def _schedule_archive_asset_catalog_icon_preload(self, delay_ms: int = 900) -> None:
            self.archive_item_icon_preload_timer.stop()
            self.archive_item_icon_preload_queue.clear()
            self.archive_item_icon_preload_next_index = 0
            if not self.archive_item_asset_catalog:
                return
            queued = 0
            for row in self.archive_item_asset_catalog:
                if not isinstance(row, Mapping):
                    continue
                if not self._archive_asset_catalog_row_values(row, "icon_paths"):
                    continue
                cache_key = self._archive_asset_catalog_icon_cache_key(row, 120)
                if cache_key in self.archive_item_icon_pixmap_cache:
                    continue
                self.archive_item_icon_preload_queue.append(dict(row))
                queued += 1
                if queued >= self.archive_item_icon_preload_limit:
                    break
            if self.archive_item_icon_preload_queue:
                self.archive_item_icon_preload_timer.start(max(0, int(delay_ms)))

        def _continue_archive_asset_catalog_icon_preload(self) -> None:
            if not self.archive_item_icon_preload_queue:
                return
            if self.worker_thread is not None:
                self.archive_item_icon_preload_timer.start(600)
                return
            loaded_count = 0
            deadline = time.monotonic() + 0.045
            while self.archive_item_icon_preload_next_index < len(self.archive_item_icon_preload_queue):
                row = self.archive_item_icon_preload_queue[self.archive_item_icon_preload_next_index]
                self.archive_item_icon_preload_next_index += 1
                if not isinstance(row, Mapping):
                    continue
                self._cached_archive_asset_catalog_inventory_icon_pixmap(row, 120)
                loaded_count += 1
                if loaded_count >= 2 or time.monotonic() >= deadline:
                    break
            if self.archive_item_icon_preload_next_index < len(self.archive_item_icon_preload_queue):
                self.archive_item_icon_preload_timer.start(80 if loaded_count else 0)
            else:
                self.archive_item_icon_preload_queue.clear()
                self.archive_item_icon_preload_next_index = 0

        def _handle_archive_item_icon_inputs_changed(self, *_args: object) -> None:
            self._clear_archive_asset_catalog_icon_cache()
            if self.archive_item_asset_catalog:
                self._schedule_archive_asset_catalog_icon_preload(delay_ms=700)

        def _archive_asset_catalog_categories(self) -> Tuple[str, ...]:
            categories = {
                str(row.get("category", "") or "").strip()
                for row in self.archive_item_asset_catalog
                if str(row.get("category", "") or "").strip()
            }
            preferred = (
                "Weapon",
                "Armor",
                "Accessory",
                "Mount / Pet",
                "Material",
                "Consumable",
                "Crafting / Recipe",
                "Tool",
                "Character Customization",
                "Gimmick / Interactive",
                "Housing / Prop",
                "Quest / Document",
                "Progression / Reward",
                "Item",
            )
            ordered = [category for category in preferred if category in categories]
            ordered.extend(sorted(category for category in categories if category not in set(preferred)))
            return tuple(ordered)

