            def _adaptive_alignment_preview_face_limit(
                submesh_count: int,
                *,
                target_total_faces: int,
                minimum: int,
                maximum: int,
            ) -> int:
                try:
                    count = max(1, int(submesh_count))
                except (TypeError, ValueError):
                    count = 1
                per_submesh = int(math.ceil(max(1, int(target_total_faces)) / float(count)))
                return max(int(minimum), min(int(maximum), per_submesh))

            def _alignment_preview_detail_mode() -> str:
                try:
                    mode = str(preview_detail_combo.currentData() or "auto").strip().lower()
                except NameError:
                    mode = "auto"
                return mode if mode in {"auto", "full", "fast"} else "auto"

            def _alignment_preview_is_interactive() -> bool:
                try:
                    return time.monotonic() < float(static_preview_interactive_until.get("time", 0.0) or 0.0)
                except Exception:
                    return False

            def _alignment_preview_widget_render_settings() -> ModelPreviewRenderSettings:
                settings = _current_alignment_preview_render_settings()
                if not _alignment_preview_is_interactive():
                    return settings
                settings = dataclasses.replace(settings)
                settings.disable_all_support_maps = True
                settings.disable_normal_map = True
                settings.disable_material_map = True
                settings.disable_height_map = True
                settings.low_quality_texture_max_dimension = min(
                    int(settings.low_quality_texture_max_dimension),
                    1024,
                )
                return clamp_model_preview_render_settings(settings)

            def _alignment_preview_source_face_limit() -> int:
                try:
                    if mesh_edit_enabled_checkbox.isChecked():
                        return 0
                except NameError:
                    pass
                if modify_original_clone_mode:
                    appended_geometry = int(source_geometry_revision.get("value", 0) or 0) > 0
                    if not appended_geometry:
                        return 0
                mesh = replacement_mesh_for_mapping or replacement_mesh_base_for_mapping
                if mesh is None:
                    return 0
                submesh_face_counts = [
                    len(getattr(submesh, "faces", ()) or ())
                    for submesh in getattr(mesh, "submeshes", ()) or ()
                    if len(getattr(submesh, "faces", ()) or ()) > 0
                ]
                total_faces = sum(submesh_face_counts)
                render_submesh_count = max(1, len(submesh_face_counts))
                if total_faces <= 80_000:
                    return 0
                preview_detail_mode = _alignment_preview_detail_mode()
                if preview_detail_mode == "full":
                    return 0
                if _alignment_preview_is_interactive() and total_faces >= 120_000:
                    return _adaptive_alignment_preview_face_limit(
                        render_submesh_count,
                        target_total_faces=45_000,
                        minimum=2_500,
                        maximum=12_000,
                    )
                if modify_original_clone_mode and int(source_geometry_revision.get("value", 0) or 0) > 0:
                    if total_faces >= 120_000:
                        return 3_000
                    if total_faces >= 40_000:
                        return 5_000
                    if total_faces >= 15_000:
                        return 8_000
                if preview_detail_mode == "auto" and total_faces <= 120_000:
                    return 0
                if preview_detail_mode == "fast" and total_faces >= 120_000:
                    return _adaptive_alignment_preview_face_limit(
                        render_submesh_count,
                        target_total_faces=50_000,
                        minimum=2_500,
                        maximum=14_000,
                    )
                if total_faces >= 250_000:
                    return _adaptive_alignment_preview_face_limit(
                        render_submesh_count,
                        target_total_faces=75_000,
                        minimum=4_000,
                        maximum=22_000,
                    )
                if total_faces >= 100_000:
                    return _adaptive_alignment_preview_face_limit(
                        render_submesh_count,
                        target_total_faces=80_000,
                        minimum=6_000,
                        maximum=30_000,
                    )
                if total_faces >= 40_000:
                    return _adaptive_alignment_preview_face_limit(
                        render_submesh_count,
                        target_total_faces=70_000,
                        minimum=10_000,
                        maximum=35_000,
                    )
                return 0

            def _alignment_preview_selected_source_face_limit(source_indices: Sequence[int]) -> int:
                try:
                    if mesh_edit_enabled_checkbox.isChecked():
                        return 0
                except NameError:
                    pass
                mesh = replacement_mesh_for_mapping or replacement_mesh_base_for_mapping
                if mesh is None:
                    return _alignment_preview_source_face_limit()
                requested_indices = tuple(
                    int(index)
                    for index in source_indices
                    if 0 <= int(index) < len(getattr(mesh, "submeshes", ()) or ())
                )
                if not requested_indices:
                    return _alignment_preview_source_face_limit()
                total_faces = sum(
                    len(getattr(mesh.submeshes[source_index], "faces", ()) or ())
                    for source_index in requested_indices
                )
                preview_detail_mode = _alignment_preview_detail_mode()
                if preview_detail_mode == "full":
                    return 0
                selected_source_index = int(selected_source_part.get("index", -1))
                if _alignment_preview_is_interactive() and total_faces >= 120_000:
                    return 18_000 if selected_source_index in requested_indices else 8_000
                if preview_detail_mode == "auto" and total_faces <= 120_000:
                    return 0
                selected_requested = selected_source_index in requested_indices
                if selected_requested:
                    if total_faces <= 80_000:
                        return 0
                    if total_faces >= 250_000:
                        return 35_000
                    if total_faces >= 100_000:
                        return 45_000
                    if total_faces >= 80_000:
                        return 55_000
                if total_faces >= 250_000:
                    return 8_000
                if total_faces >= 100_000:
                    return 12_000
                return _alignment_preview_source_face_limit()

            def _alignment_preview_background_source_face_limit(source_indices: Sequence[int]) -> int:
                try:
                    if mesh_edit_enabled_checkbox.isChecked():
                        return 0
                except NameError:
                    pass
                mesh = replacement_mesh_for_mapping or replacement_mesh_base_for_mapping
                if mesh is None:
                    return _alignment_preview_source_face_limit()
                requested_indices = tuple(
                    int(index)
                    for index in source_indices
                    if 0 <= int(index) < len(getattr(mesh, "submeshes", ()) or ())
                )
                if not requested_indices:
                    return _alignment_preview_source_face_limit()
                total_faces = sum(
                    len(getattr(mesh.submeshes[source_index], "faces", ()) or ())
                    for source_index in requested_indices
                )
                preview_detail_mode = _alignment_preview_detail_mode()
                if preview_detail_mode == "full":
                    return 0
                if _alignment_preview_is_interactive() and total_faces >= 120_000:
                    return 2_000
                if preview_detail_mode == "auto" and total_faces <= 120_000:
                    return 0
                if total_faces >= 250_000:
                    return 2_500
                if total_faces >= 100_000:
                    return 3_500
                if total_faces >= 40_000:
                    return 5_000
                return _alignment_preview_source_face_limit()

            def _configure_alignment_tree(
                tree: QTreeWidget,
                widths: Sequence[int],
                *,
                max_height: int = 0,
                stretch_columns: Sequence[int] = (),
                persist_key: str = "",
            ) -> None:
                tree.setRootIsDecorated(False)
                tree.setAlternatingRowColors(True)
                tree.setMouseTracking(True)
                tree.viewport().setMouseTracking(True)
                tree.setUniformRowHeights(True)
                tree.setTextElideMode(Qt.ElideMiddle)
                tree.setWordWrap(False)
                tree.setMinimumWidth(0)
                tree.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                tree.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                tree.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
                tree.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                tree.setSelectionMode(QAbstractItemView.SingleSelection)
                tree.setStyleSheet(tree.styleSheet() + "QTreeWidget::item { padding: 0 2px; }")
                header = tree.header()
                header.setSectionsClickable(True)
                header.setMinimumSectionSize(28)
                header.setStretchLastSection(True)
                header.setSectionsMovable(False)
                stretch_column_set = set(int(column) for column in stretch_columns)
                if not stretch_column_set and widths:
                    stretch_column_set.add(len(widths) - 1)
                for column, width in enumerate(widths):
                    if column in stretch_column_set:
                        header.setSectionResizeMode(column, QHeaderView.Stretch)
                    else:
                        header.setSectionResizeMode(column, QHeaderView.Interactive)
                    tree.setColumnWidth(column, int(width))
                if persist_key:
                    make_tree_columns_persistent(
                        tree,
                        self.settings,
                        f"alignment/{persist_key}",
                        minimum_width=28,
                        save_callback=self.schedule_settings_save,
                        restore_later=False,
                        persist_order=False,
                        sections_movable=False,
                    )
                    header.setStretchLastSection(True)
                if max_height > 0:
                    tree.setMaximumHeight(max_height)

