                part_offset_z_spin = _part_spin(0.0, -10.0, 10.0, 5, 0.0005)
                part_rotate_x_spin = _part_spin(0.0, -360.0, 360.0, 2, 0.10, " deg")
                part_rotate_y_spin = _part_spin(0.0, -360.0, 360.0, 2, 0.10, " deg")
                part_rotate_z_spin = _part_spin(0.0, -360.0, 360.0, 2, 0.10, " deg")
                part_scale_x_spin = _part_spin(1.0, 0.001, 100.0, 4, 0.005)
                part_scale_y_spin = _part_spin(1.0, 0.001, 100.0, 4, 0.005)
                part_scale_z_spin = _part_spin(1.0, 0.001, 100.0, 4, 0.005)
