                part_transform_sliders: Dict[QDoubleSpinBox, QSlider] = {}

                def _part_transform_slider(
                    spin: QDoubleSpinBox,
                    *,
                    scale: float,
                    tooltip: str,
                ) -> QSlider:
                    slider = QSlider(Qt.Horizontal)
                    slider.setObjectName("AlignmentPartTransformSlider")
                    slider.setToolTip(tooltip)
                    slider.setMinimum(int(round(float(spin.minimum()) * scale)))
                    slider.setMaximum(int(round(float(spin.maximum()) * scale)))
                    slider.setSingleStep(max(1, int(round(float(spin.singleStep()) * scale))))
                    slider.setPageStep(max(slider.singleStep(), slider.singleStep() * 10))
                    slider.setValue(int(round(float(spin.value()) * scale)))
                    slider.setMinimumWidth(72)

                    def _sync_slider_from_spin(value: float, *, target_slider: QSlider = slider, slider_scale: float = scale) -> None:
                        slider_value = int(round(float(value) * slider_scale))
                        if target_slider.value() == slider_value:
                            return
                        target_slider.blockSignals(True)
                        target_slider.setValue(slider_value)
                        target_slider.blockSignals(False)

                    def _sync_spin_from_slider(value: int, *, target_spin: QDoubleSpinBox = spin, slider_scale: float = scale) -> None:
                        spin_value = float(value) / float(slider_scale)
                        if abs(float(target_spin.value()) - spin_value) <= max(1e-9, float(target_spin.singleStep()) * 0.1):
                            return
                        target_spin.setValue(spin_value)

                    spin.valueChanged.connect(_sync_slider_from_spin)
                    slider.valueChanged.connect(_sync_spin_from_slider)
                    part_transform_sliders[spin] = slider
                    return slider

                def _part_spin_with_slider(
                    spin: QDoubleSpinBox,
                    *,
                    scale: float,
                    tooltip: str,
                ) -> QWidget:
                    wrapper = QWidget()
                    wrapper_layout = QVBoxLayout(wrapper)
                    wrapper_layout.setContentsMargins(0, 0, 0, 0)
                    wrapper_layout.setSpacing(1)
                    wrapper_layout.addWidget(spin)
                    wrapper_layout.addWidget(_part_transform_slider(spin, scale=scale, tooltip=tooltip))
                    return wrapper

                def _sync_part_slider_from_spin(spin: QDoubleSpinBox) -> None:
                    slider = part_transform_sliders.get(spin)
                    if slider is None:
                        return
                    scale = 2000.0 if spin in (part_offset_x_spin, part_offset_y_spin, part_offset_z_spin) else 10.0 if spin in (part_rotate_x_spin, part_rotate_y_spin, part_rotate_z_spin) else 1000.0
                    slider_value = int(round(float(spin.value()) * scale))
                    if slider.value() == slider_value:
                        return
                    slider.blockSignals(True)
                    slider.setValue(slider_value)
                    slider.blockSignals(False)

